(function(root,factory){
  const api=factory();
  if(typeof module!=="undefined"&&module.exports)module.exports=api;
  else root.CareerModeGazetteCopy=api;
})(typeof globalThis!=="undefined"?globalThis:this,function(){
  "use strict";

  // HO-041 Touchline Gazette copy (built by gazette/copy/build_copy.py from the checked batches).
  // stories: front-page lead stories by situation and edition. duets: two-voice commentary (lead + co), show on a two-line bar.
  // small: briefs, captions (by photo), ears and quotes. Fill {placeholders} like frontPages.js.
  const freeze=list=>Object.freeze(list.map(row=>Object.freeze(row)));
  const STORIES=freeze([
    {"id":"s-001","situation":"big-win","edition":"season","byline":"From our touchline desk","standfirst":"{winner} did not so much win season {seasonNo} as finish it, and {loser} is left reading the table from the far end of the room.","paragraphs":["Some seasons are a fight. This one was a procession. {winnerClub} ended {margin} clear of {loserClub}, and the only suspense left was how politely anyone could mention it.","The tally of {winnerPoints} against {loserPoints} needs no adjectives. {loser} will treat it as a lesson rather than a verdict, and the Gazette suspects the revision timetable is already drawn up.","Season {seasonNo} of {seasonsTotal} is in the book. The rivalry, as ever, is not."],"pullquote":{"text":"That was not a gap. That was a different postcode.","who":"A Gazette columnist"}},
    {"id":"s-002","situation":"big-win","edition":"season","byline":"Our chief football correspondent","standfirst":"Rarely does a season name its winner so early and so plainly, and {winnerClub} wore the finish as though it had been tailored.","paragraphs":["The best campaigns settle their business early and spend the rest in celebration. {winner} guided {winnerClub} home {margin} clear of {loser} and {loserClub}, and the closing weeks felt like a lap of honour.","{loser} deserves a fair word, because chasing a lead this size takes nerve. Still, {winnerPoints} to {loserPoints} is a verdict that will be quoted for a good while.","Expect a response. Rivals who finish this far back tend to arrive early next time."],"pullquote":{"text":"They did not win the season. They moved into it.","who":"The press box"}},
    {"id":"s-003","situation":"big-win","edition":"season","byline":"Reported from the directors' box","standfirst":"From the directors' box the view was unmistakable, with {winner} high above the table and {loser} waving politely from below.","paragraphs":["Directors like a tidy season, and this one was spotless. {winnerClub} finished {margin} ahead, and the box agreed that {winner} had run the whole campaign like a well-kept ledger.","{loserClub} will not enjoy the arithmetic of {winnerPoints} against {loserPoints}. Yet {loser} has the temperament for a comeback, and the gap is a number, not a destiny.","Season {seasonNo} closes with one manager serene and the other sharpening a pencil."],"pullquote":{"text":"A lead like that is built in every week, never in a day.","who":"A veteran of the box"}},
    {"id":"s-004","situation":"big-win","edition":"season","byline":"From the press gallery","standfirst":"{winner} left season {seasonNo} with a lead so wide that {loser} might need a map and a good pair of boots to close it.","paragraphs":["Gaps like this do not happen by accident. {winner} ran {winnerClub} with a steady hand all year and finished {margin} ahead of {loserClub}, which is the sort of margin that makes pundits quiet.","There is no shame in being second to a season this assured. {loser} still took {loserPoints} and will carry plenty of material into the next chapter.","The gallery's advice is simple. Keep your eyes on the leader and your boots laced."],"pullquote":{"text":"Some leads are earned. This one was practically framed.","who":"A Gazette columnist"}},
    {"id":"s-005","situation":"big-win","edition":"season","byline":"Our rivalry correspondent","standfirst":"The rivalry has seen close finishes and bitter finishes, but season {seasonNo} was neither, since {winner} simply pulled away.","paragraphs":["Every rivalry needs a season like this to remind it how wide a table can open. {winnerClub} finished {margin} in front, and {loserClub} spent the final stretch looking up the standings with admiration.","The tally of {winnerPoints} points to {loserPoints} is the headline, but the story underneath is calmer. {winner} never let the pace drop, and {loser} could never quite close the distance.","Round {seasonsTotal} of the argument is a long way from over."],"pullquote":{"text":"A good rival makes the gap look bigger and the comeback sweeter.","who":"The rivalry desk"}},
    {"id":"s-006","situation":"big-win","edition":"season","byline":"From the statistician's corner","standfirst":"The statisticians reached for their widest column to record season {seasonNo}, where {winner} finished {margin} clear of {loser}.","paragraphs":["A table can lie about a close race, but it cannot hide a rout. {winnerClub} totalled {winnerPoints}, {loserClub} totalled {loserPoints}, and the subtraction left the corner in a respectful hush.","By any measure the season belonged to {winner}. The pace was steady, the results were firm and the gap grew without ceremony until it could no longer be ignored.","{loser} will study these figures closely. Good numbers can be rewritten, and the next season is already open."],"pullquote":{"text":"The figures do not argue. They just keep adding up.","who":"The scorers' table"}},
    {"id":"s-007","situation":"comfortable-win","edition":"season","byline":"From our touchline desk","standfirst":"Season {seasonNo} went to {winner} by a comfortable distance, with {loser} close enough to see the finish but never quite to touch it.","paragraphs":["There was no photo finish and no late drama. {winnerClub} finished {margin} ahead of {loserClub}, a lead built week by week and held without fuss.","{loser} made the pursuit honest, and {loserPoints} is a total that deserved better luck. But {winnerPoints} is simply a better number, and {winner} knew precisely how to protect it.","Season {seasonNo} of {seasonsTotal} is done. The next one begins with a fresh table and a short memory."],"pullquote":{"text":"Comfortable is the politest word for convincing.","who":"A Gazette columnist"}},
    {"id":"s-008","situation":"comfortable-win","edition":"season","byline":"By the Gazette football desk","standfirst":"Quiet authority carried {winner} through season {seasonNo}, and {loser} had to settle for a front-row view of the finish.","paragraphs":["Not every title needs fireworks. {winnerClub} won steadily, finished {margin} clear and never gave {loserClub} a real sniff of the lead in the closing stretch.","For {loser} the season was solid but not enough. The tally of {loserPoints} would have won in plenty of years, and that is the cruel charm of a rivalry with a strong opponent.","Everything now turns to the next campaign, where authority will be tested again."],"pullquote":{"text":"The best wins look easy, and never are.","who":"The football desk"}},
    {"id":"s-009","situation":"comfortable-win","edition":"season","byline":"Our rivalry correspondent","standfirst":"A lead of {margin} sounds modest on paper, but {winner} made it feel like a wall as season {seasonNo} closed.","paragraphs":["Rivalry reporters learn to read between the lines of a table. {winnerClub} stayed ahead of {loserClub} through the closing weeks, and {margin} was a gap {loser} could see but never bridge.","The tally of {winnerPoints} against {loserPoints} reads as a fair result. {winner} earned the lead and {loser} earned the respect, which in this contest is a currency of its own.","The ledger turns to season {seasonNo} plus one, and nothing is settled."],"pullquote":{"text":"Nobody ran away with it. They just kept walking faster.","who":"The rivalry desk"}},
    {"id":"s-010","situation":"comfortable-win","edition":"season","byline":"From the Gazette press gallery","standfirst":"With season {seasonNo} done, {winner} has the edge, and {loser} has a very good reason to start the next one early.","paragraphs":["The Gazette press gallery watched the closing weeks from the cheap seats, and the verdict was unanimous. {winnerClub} controlled the finish and ended {margin} in front of {loserClub}.","There were moments when {loser} threatened to narrow the gap. None lasted, and {winner} had an answer ready every time, which is what separates a good season from a winning one.","Next year's gallery will be full. Everyone wants to see the reply."],"pullquote":{"text":"You can feel a rival lean in. Then you feel them run out of road.","who":"A Gazette columnist"}},
    {"id":"s-011","situation":"comfortable-win","edition":"season","byline":"Gazette football desk","standfirst":"Calm hands won season {seasonNo} for {winner}, who steered {winnerClub} home {margin} ahead of a game and persistent {loser}.","paragraphs":["Calm is underrated in a rivalry. {winner} kept the pace sensible and the results steady, and the table rewarded {winnerClub} with {winnerPoints} and a healthy cushion.","{loserClub} finished on {loserPoints}, a total of real quality, and {loser} can hold their head high. The margin hurts only because the standard was so high.","Season {seasonNo} of {seasonsTotal} will be remembered as the one that stayed under control."],"pullquote":{"text":"Steady wins seasons, and showy wins applause.","who":"The Gazette desk"}},
    {"id":"s-012","situation":"comfortable-win","edition":"season","byline":"By our senior correspondent","standfirst":"Our senior correspondent has seen plenty of campaigns, and few have been settled as tidily as {winner} settled season {seasonNo}.","paragraphs":["The shape of the season was clear by the closing weeks. {winnerClub} led, {loserClub} chased, and the final table showed {winnerPoints} against {loserPoints}, a gap of {margin} that nobody could argue with.","{loser} produced a respectable campaign, and the Gazette does not for a moment suggest otherwise. It simply happened to meet a slightly better one.","The reply is next, and rivals of this temperament always have one."],"pullquote":{"text":"It was not a landslide. It was a very firm nudge.","who":"A senior columnist"}},
    {"id":"s-013","situation":"narrow-win","edition":"season","byline":"From our touchline desk","standfirst":"The margin was thin enough to read through, and {winner} edged season {seasonNo} by {margin} over a defiant {loser}.","paragraphs":["A season this close is decided in the margins, and the margins were kind to {winnerClub}. It ended {margin} ahead of {loserClub}, with {winnerPoints} against {loserPoints} on the board.","{loser} will replay a handful of moments for weeks. That is the lot of the runner-up in a race like this, and it is also the fuel for what comes next.","Season {seasonNo} of {seasonsTotal} ends with one very happy manager and one very close call."],"pullquote":{"text":"Thin margins make loud memories.","who":"A Gazette columnist"}},
    {"id":"s-014","situation":"narrow-win","edition":"season","byline":"By our senior correspondent","standfirst":"It took the very last pages of season {seasonNo} to settle things, and {winner} came through by {margin} to take the honours.","paragraphs":["Nerves were on show in both camps. In the end {winnerClub} held firm, finished {margin} ahead and left {loserClub} to wonder how a season so well fought could end so narrowly.","{loser} earned {loserPoints} and the full respect of the press box. Close results sting more, but they also tend to produce the best second acts.","The rematch is already circled in red. Season {seasonNo} was merely the opening round of a long argument."],"pullquote":{"text":"Close enough to touch. Far enough to hurt.","who":"The senior desk"}},
    {"id":"s-015","situation":"narrow-win","edition":"season","byline":"From the press box","standfirst":"From the press box it looked like a coin toss until the end, but {winner} called it right and finished season {seasonNo} ahead by {margin}.","paragraphs":["The whole box held its breath. {winnerClub} and {loserClub} traded the lead in spirit all year, and only the closing table showed that {winner} had held on by {margin}.","No one could call {loser} unlucky, only unrewarded. The tally of {loserPoints} is a total that would please most managers, and {winnerPoints} simply pleased one more.","That is how rivalries are kept honest."],"pullquote":{"text":"Next season, the coin gets tossed again.","who":"The press box"}},
    {"id":"s-016","situation":"narrow-win","edition":"season","byline":"Our chief football writer","standfirst":"Our chief football writer calls it the closest kind of victory, where {winner} held {loser} off by {margin} and not a point more.","paragraphs":["Narrow wins have a flavour of their own. {winnerClub} did not dominate, did not coast and did not flinch, and the result was a lead of {margin} that felt larger than it looked.","{loserClub} pushed to the last, and {loser} should be proud of a total of {loserPoints}. Little separated the sides, which is just how this rivalry likes it.","Season {seasonNo} has a winner, but the argument has no end."],"pullquote":{"text":"A narrow win still counts in full. That is the cruelty of arithmetic.","who":"A Gazette columnist"}},
    {"id":"s-017","situation":"narrow-win","edition":"season","byline":"From our rivalry desk","standfirst":"The rivalry desk has rarely seen a gap so slim hold so firm, as {winner} finished season {seasonNo} just {margin} ahead of {loser}.","paragraphs":["There is a particular tension in a season that could have gone either way. {winnerClub} edged it, {loserClub} pressed to the end, and the table shows {winnerPoints} against {loserPoints} with almost nothing between.","{winner} took the honours and {loser} took the notes. Both will be better for it, and the Gazette expects the next meeting to be as tight.","Season {seasonNo} of {seasonsTotal} proves once more that the rivalry is not for the faint-hearted."],"pullquote":{"text":"A season this close deserves two trophies and one engraver.","who":"The rivalry desk"}},
    {"id":"s-018","situation":"narrow-win","edition":"season","byline":"By our archive correspondent","standfirst":"The archive correspondent opened the old files and found few seasons as tight as this one, where {winner} won by just {margin}.","paragraphs":["Archives are full of comfortable winners. Rarer is a finish like this, with {winnerClub} ahead of {loserClub} by the slimmest of gaps and the outcome in doubt almost to the final tally.","The tally of {winnerPoints} against {loserPoints} will be filed with care. {loser} should know that the folder is labelled close, and that close is a respectable thing to be.","The archive has space for season {seasonNo} plus one. Come and fill it."],"pullquote":{"text":"History remembers the winners. It quietly respects the near misses.","who":"The archive"}},
    {"id":"s-019","situation":"draw","edition":"season","byline":"From our touchline desk","standfirst":"{managerA} and {managerB} finished season {seasonNo} on {points} points apiece, and the Gazette must report that the record holds no winner.","paragraphs":["Nothing separated {clubA} and {clubB} when season {seasonNo} closed. Both managers ended on {points} points, and the space for a victor's name now carries two names in equal type.","It is a rare result in a rivalry built on comparison. {managerA} cannot claim the better season and {managerB} cannot concede one, so honour stays intact and a grievance stays unjustified.","Season {seasonNo} of {seasonsTotal} goes into the archive as a shared page."],"pullquote":{"text":"A dead heat is the rival's way of saying maybe next time.","who":"A Gazette columnist"}},
    {"id":"s-020","situation":"draw","edition":"season","byline":"By our chief correspondent","standfirst":"Season {seasonNo} ends with {clubA} and {clubB} locked together on {points} points, a result the record books will list without a victor.","paragraphs":["The ledger closed on identical entries. {managerA} of {clubA} and {managerB} of {clubB} each collected {points} points, and the Gazette finds no champion to crown and nobody to console.","Rivalries are usually defined by who blinked first. Here neither blinked, and each manager can fairly say the other gave everything.","Across {seasonsTotal} seasons, a level year changes little on paper and a great deal in the mind."],"pullquote":{"text":"Neither blinked. The table just shrugged.","who":"The chief desk"}},
    {"id":"s-021","situation":"draw","edition":"season","byline":"From the press gallery","standfirst":"Mirror images in the standings, as {managerA} and {managerB} both finish season {seasonNo} on {points} points and neither can look down on the other.","paragraphs":["Hold the two seasons to the light and they match exactly. {clubA} brought {points} points to the finish and so did {clubB}, leaving {managerA} and {managerB} staring across an even page.","A draw asks more of the spectator than a decisive result. There is no hero to cheer and no villain to blame, only equal competitors and an unresolved argument between friends.","The argument resumes next season with no advantage claimed."],"pullquote":{"text":"You could lay a ruler across those seasons and it would sit flat.","who":"The press gallery"}},
    {"id":"s-022","situation":"draw","edition":"season","byline":"From our honours desk","standfirst":"No single name goes on top this time, because {managerA} and {managerB} finished season {seasonNo} with the same {points} points each.","paragraphs":["The honours board keeps room for a single name per season, and this year it has been asked to hold both. {clubA} and {clubB} ended level on {points} points, and the board will simply have to share.","Neither manager has a triumph to tell, and neither has a disappointment. Seasons of identical value, in a rivalry this keen, are their own kind of compliment.","The engraver can put down the chisel. Season {seasonNo} of {seasonsTotal} is complete."],"pullquote":{"text":"There was room on the board for a champion. Nobody asked for it.","who":"The honours desk"}},
    {"id":"s-023","situation":"draw","edition":"season","byline":"From our court correspondent","standfirst":"Patience is the lesson of season {seasonNo}, which ended with {clubA} and {clubB} on {points} points each and the argument adjourned.","paragraphs":["Judgement will have to wait. The season meant to separate {managerA} and {managerB} gave each of them {points} points instead, and both cases stand exactly where they began.","Adjourned is the right word. Nobody has been refused anything, because nobody was owed anything. The court of opinion needs another sitting.","That sitting is already booked in the form of next season."],"pullquote":{"text":"Case adjourned. Bring better evidence next time, both of you.","who":"The court desk"}},
    {"id":"s-024","situation":"draw","edition":"season","byline":"From the scorers' table","standfirst":"The scales settled flat in season {seasonNo}, with {managerA} and {managerB} each holding {points} points and neither pan dropping an inch.","paragraphs":["A pair of scales has a simple honesty, and this year it reads level. {clubA} placed {points} points on one side, {clubB} placed {points} on the other, and the beam did not tremble.","It makes for a fair account of the season. {managerA} can point to a campaign of real worth, and so can {managerB}, and nobody in good faith could call either lighter.","The scales will be loaded again next season, and the Gazette will watch the beam closely."],"pullquote":{"text":"Weigh them as carefully as you like. They come out the same.","who":"The scorers' table"}},
    {"id":"s-025","situation":"champions-league","edition":"season","byline":"From the European football desk","standfirst":"The Champions League belongs to {winner}, whose European triumph gives the season a distinction beyond the usual rivalry ledger.","paragraphs":["Some trophies reward a good campaign. The Champions League gives a campaign its defining sentence. With {winnerClub} crowned in Europe, {winner} has supplied this season of the Showdown with a result that needs no embellishment.","For {loser}, the achievement is formidable without being final in every sense. The rivalry still belongs to both managers, and other honours retain their value. Yet this is the distinction against which the season will primarily be measured.","A cabinet now has its centrepiece. Whatever comes after, this edition of the Gazette will remember who placed it there."],"pullquote":{"text":"There are honours you count, and honours that change how the counting feels.","who":"A Gazette columnist"}},
    {"id":"s-026","situation":"champions-league","edition":"season","byline":"From our rivalry correspondent","standfirst":"For all the attention on {winner}'s European crown, {loser} remains an essential part of what makes the achievement matter.","paragraphs":["An achievement acquires a different force when someone trusted is there to measure it. {winner} has won the Champions League, and the familiar comparison with {loser} turns that European honour into a particularly resonant Showdown moment.","It would be a mistake to treat {loser} as mere scenery for somebody else's success. A lasting rivalry is built on an opponent capable of giving every honour context, and on the understanding that admiration need not mean surrender.","For now, the recognition belongs with {winnerClub}. The respect that surrounds it belongs to a competition in which neither manager has become irrelevant."],"pullquote":{"text":"A worthy rival does not diminish a trophy. A worthy rival gives it depth.","who":"A Gazette columnist"}},
    {"id":"s-027","situation":"champions-league","edition":"season","byline":"From the editorial football desk","standfirst":"In a contest built on comparison, {winner} has earned a distinction that requires no reference to the other manager.","paragraphs":["Not every important sentence in a rivalry needs the rival's name. {winner} has led {winnerClub} to the Champions League, and the achievement stands on its own before it becomes a point of comparison with anything else.","This matters in a Showdown where the temptation is always to ask what {loser} did in return. That question has its place, but it should follow rather than interrupt recognition of a European title properly won.","The competition between friends will recover its familiar rhythm. For now, there is an honour to acknowledge without a qualification attached."],"pullquote":{"text":"Comparison gives the contest its shape. Achievement gives it something worth comparing.","who":"A Gazette columnist"}},
    {"id":"s-028","situation":"champions-league","edition":"season","byline":"Dispatch from the archive desk","standfirst":"The European title has supplied the Showdown archive with a clear landmark, attached permanently to {winner} and {winnerClub}.","paragraphs":["Open an old sporting archive and the details are often crowded, but the principal honours survive in the margins. This season has provided such an entry: {winner} has taken {winnerClub} to the Champions League crown.","The importance of the entry is not that it settles every debate with {loser}. It is that future readings of the rivalry will find a definite European achievement, rather than a claim dependent on opinion or nostalgia.","The ink is barely dry in the Gazette's imagined record book. Already, the most important line is unlikely to need revision."],"pullquote":{"text":"Memory can exaggerate a season. A European title requires no assistance from memory.","who":"The archive editor"}},
    {"id":"s-029","situation":"champions-league","edition":"season","byline":"The Touchline Gazette's lead writer","standfirst":"With the Champions League secured, {winner} has turned a question of ambition into a matter of established achievement.","paragraphs":["Ambition is easy to declare and difficult to file as evidence. {winner} has gone beyond aspiration by delivering the Champions League for {winnerClub}, placing a European title in a season that will be remembered for a concrete distinction.","The result also improves the quality of the rivalry's argument. {loser} is no longer being compared with a promise or a projection, but with an honour that has actually been secured and entered into the Showdown record.","That is the useful finality of silverware. The future can be contested, debated and imagined, while the trophy already belongs in the present tense."],"pullquote":{"text":"Promise is an attractive headline. Proof is the stronger story.","who":"A Gazette columnist"}},
    {"id":"s-030","situation":"champions-league","edition":"season","byline":"From the Gazette's closing column","standfirst":"For {winner}, the Champions League has supplied an enduring answer to football's simplest question: what was won?","paragraphs":["When the season is reduced to its essentials, {winner} will have a wonderfully direct answer. {winnerClub} won the Champions League. Much else may be said about the Showdown, but none of it can make that achievement less definite.","It is an answer that {loser} can acknowledge without conceding the value of a separate campaign. Both managers are linked by comparison, not obliged to regard every piece of the other's success as a personal defeat.","The Gazette closes its report with the trophy itself. No imagined speech is required, and no exaggerated promise about tomorrow could improve the final line."],"pullquote":{"text":"End the argument where the evidence is strongest: with the trophy.","who":"The closing desk"}},
    {"id":"s-031","situation":"europa-league","edition":"season","byline":"From the continental desk","standfirst":"European silverware has found its way to {winnerClub}, giving {winner} a lasting achievement in a season shared with a familiar rival.","paragraphs":["The Europa League trophy has a new home in this Showdown. {winner} has claimed it with {winnerClub}, placing a continental honour at the heart of a season that will now carry a European distinction of its own.","The result gives {loser} something substantial to answer, but it does not make the rival's efforts disposable. This contest is built on separate campaigns judged together, and a European title deserves its own place within that comparison.","Long after the season's figures have been filed, the achievement will remain straightforward: {winnerClub} finished this European competition as its champion."],"pullquote":{"text":"A European trophy needs no borrowed grandeur to justify its place.","who":"A Gazette columnist"}},
    {"id":"s-032","situation":"europa-league","edition":"season","byline":"Our correspondent on honours","standfirst":"The Europa League victory gives {winner} something more durable than an impressive entry in the seasonal points record.","paragraphs":["An entry in the Showdown ledger can be read in a moment. What stands behind this one is larger: {winner} has guided {winnerClub} to the Europa League title, a concrete honour rather than an interpretation of form.","For {loser}, the distinction matters because the rivalry measures accomplishments, not simply competing opinions about them. A trophy provides evidence that both managers can recognise, even as they continue to value their own seasons differently.","In the archive, the figures will sit beside the title. Neither needs exaggerating, and together they explain why this European success merits the front page."],"pullquote":{"text":"Figures record the contest. The cup tells us what one campaign achieved.","who":"The Gazette archive editor"}},
    {"id":"s-033","situation":"europa-league","edition":"season","byline":"The Gazette rivalry correspondent","standfirst":"{loser} has a European triumph to measure against, after {winner} turned this season into a title-winning campaign for {winnerClub}.","paragraphs":["Respect is easiest to recognise when the achievement belongs to somebody else. {loser} has watched a rival manager claim the Europa League with {winnerClub}, an outcome that commands attention even inside a competition designed for friendly argument.","That is the particular strength of this Showdown. The managers remain opponents, yet the honours have meaning beyond their contest. {winner} takes the European title, while {loserClub} continues to stand for a separate campaign and its own ambitions.","No tribute requires a concession about the future. This edition records a deserved title and leaves the next chapter free to belong to either manager."],"pullquote":{"text":"A proper rivalry can recognise a fine achievement without losing its appetite.","who":"The press box"}},
    {"id":"s-034","situation":"europa-league","edition":"season","byline":"Our writer on European football","standfirst":"{winnerClub} has secured the Europa League, an achievement that merits recognition on its own terms rather than by comparison with another trophy.","paragraphs":["There is no need to borrow prestige from a different competition. The Europa League offers a European title in its own right, and {winner} has won it with {winnerClub} during a season that now carries that distinction.","The temptation in a rivalry is to rank every honour before the congratulations are finished. Yet {loser} and {winner} are better served by an honest account: this is a significant continental achievement, whatever else the seasonal comparison contains.","When the Gazette returns to this campaign, it will not need a grander name for the cup. Winning the Europa League is enough."],"pullquote":{"text":"Call the competition by its name, then give the champions their due.","who":"The press box"}},
    {"id":"s-035","situation":"europa-league","edition":"season","byline":"The continental honours correspondent","standfirst":"The achievement of {winnerClub} adds a European chapter to a competition whose central drama belongs to two managers.","paragraphs":["Consider the distance between a private competition and a continental title. Career Mode Showdown belongs to two friends, yet {winner}'s Europa League victory with {winnerClub} draws on a stage far larger than their head-to-head comparison.","That contrast gives the rivalry much of its charm. {loser} is still the direct competitor, the person against whom a season is assessed, while the European honour carries an independent meaning that does not depend on any teasing afterwards.","The Gazette can hold both perspectives on the same page: a trophy won in Europe and a friendly challenge made more interesting by it."],"pullquote":{"text":"Their contest is intimate, but its achievements can have a continental scale.","who":"The Gazette features editor"}},
    {"id":"s-036","situation":"europa-league","edition":"season","byline":"The European record correspondent","standfirst":"The season's European result will remain legible in the archives long after the surrounding arguments have faded.","paragraphs":["Archives favour statements that do not need explaining. This season offers one: {winnerClub} won the Europa League, with {winner} in charge. It is the sort of entry that keeps its meaning when the surrounding context has grown distant.","The record of {loser}'s campaign belongs alongside it, because the Showdown is a shared undertaking even when its honours are not shared. The trophy introduces an important distinction, not a licence to diminish the other side of the rivalry.","Future readers will find no invented flourish necessary. A European title, its winning manager and its club are enough to preserve the moment."],"pullquote":{"text":"Good archives keep the achievement and discard the unnecessary noise.","who":"The Gazette archivist"}},
    {"id":"s-037","situation":"league-title","edition":"season","byline":"From the football editor's desk","standfirst":"For {winner}, the league championship gives a season its defining distinction and {winnerClub} a claim that needs no embellishment.","paragraphs":["There are honors that decorate a season and honors that define it. The league title belongs firmly in the latter category. {winner} has secured that distinction for {winnerClub}, placing a championship at the center of this season's account.","For {loser}, the comparison is not diminished by the achievement on the other side. The Showdown rewards a range of honors, yet a league championship carries its own unmistakable authority within that reckoning. It is a substantial marker in a rivalry measured through seasons.","When the broader contest is remembered, the title will not require an elaborate explanation. It is the sort of achievement that can stand alone on the page."],"pullquote":{"text":"A championship is a complete sentence in the language of football.","who":"A Gazette columnist"}},
    {"id":"s-038","situation":"league-title","edition":"season","byline":"Our chief writer reports","standfirst":"The league title is the ultimate domestic endorsement, and {winner} now possesses it with {winnerClub}.","paragraphs":["League football asks a broader question than any individual cup can answer: who deserves to be called champion? For this season, the title has gone to {winnerClub} under {winner}. It is a verdict with a special weight.","The Showdown offers {loser} plenty of reasons to remain invested in the contest, because no single kind of achievement tells every story. Nevertheless, the league crown carries a particular clarity. There is no need to turn its significance into an argument.","The next installment of the rivalry will bring its own judgments. This one has already supplied a defining answer, written in the simplest possible terms: league champions."],"pullquote":{"text":"Domestic football has issued its verdict, and the wording is wonderfully plain.","who":"The press box"}},
    {"id":"s-039","situation":"league-title","edition":"season","byline":"From the rivalry correspondence desk","standfirst":"{winner}'s league championship strengthens the season's record while giving {loser} a distinguished standard to answer.","paragraphs":["Rivalries are often sustained not by hostility but by the quality of the challenge. {winner} has raised that standard with a league title for {winnerClub}. It is a significant achievement, and the season's record is richer for it.","The other managerial story deserves its proper space. {loser} is not a footnote to this championship. Both participants build their own reputations across the Showdown. A title can shape the current comparison without determining the value of every campaign still to come.","Such contests become worth following when their achievements demand a response. The league crown has given this rivalry a particularly distinguished point of reference."],"pullquote":{"text":"The finest rivalries are improved whenever either manager raises the standard.","who":"A Gazette columnist"}},
    {"id":"s-040","situation":"league-title","edition":"season","byline":"From the editorial analysis desk","standfirst":"The league championship offers {winner} something rarer than a favorable interpretation: an achievement beyond dispute.","paragraphs":["Debates over the finest season can travel in many directions, from points to the character of particular honors. There is far less room for debate about a league champion. {winner} has brought that title to {winnerClub}.","That certainty should not be mistaken for a verdict on everything {loser} has accomplished. The Showdown compares the managers through an agreed range of achievements. Within that wider framework, the domestic title is an especially compelling piece of evidence for one campaign.","Arguments over relative greatness can wait for the full account. The championship itself is settled, and the simplicity of that fact gives it unusual force."],"pullquote":{"text":"Opinions may wander, but the name of the champion stays put.","who":"The press box"}},
    {"id":"s-041","situation":"league-title","edition":"season","byline":"From the record room","standfirst":"The season's archive has gained a particularly durable entry: {winnerClub} and {winner} are league champions.","paragraphs":["An archive preserves what the passing excitement of a season might otherwise blur. This entry requires no elaborate caption: {winner} has won the league title with {winnerClub}. The distinction belongs in the permanent account of this Showdown.","Records also demand proportion. They should preserve {loser}'s contributions to the rivalry without allowing a single championship to swallow the rest of the story. Each season supplies its own material, and each manager remains responsible for an independent body of achievement.","Years from now, if the contest is reopened for a fresh reading, the domestic title will still be there. Its significance needs no revision."],"pullquote":{"text":"Memory may change its emphasis, but a championship remains on the record.","who":"A Gazette archivist"}},
    {"id":"s-042","situation":"league-title","edition":"season","byline":"The Gazette's language and football correspondent","standfirst":"It takes remarkably few words to describe {winner}'s achievement, and none of them can be taken lightly.","paragraphs":["Champions. The word is brief, but it contains a considerable sporting claim. This season it applies to {winnerClub}, whose league title has been secured under {winner}. In a newspaper full of competing descriptions, this is the one that matters most.","The word should not be used to belittle the work of {loserClub}. Rival achievements can coexist, and the Showdown is richer when they are considered fairly. Yet the domestic title grants one club a designation that requires neither apology nor qualification.","A good headline sometimes needs almost nothing beyond the truth. This is such a case: the league has its champion, and the season has its signature achievement."],"pullquote":{"text":"Few words in football are shorter, or heavier, than champions.","who":"The press box"}},
    {"id":"s-043","situation":"comeback","edition":"season","byline":"From our chief football desk","standfirst":"A season once framed by the overall deficit has become {winner}'s reply, with {loser}'s advantage cut down to size.","paragraphs":["The most important result of {winner}'s season is not simply the victory over {loser}. It is what that victory has done to the contest beyond it. A manager who entered with ground to recover has recovered some of it.","This is how a long rivalry changes its character. An earlier advantage still belongs in the account, but it no longer tells the entire story. {winnerClub} has supplied fresh evidence that the contest is capable of changing direction.","The next chapter will begin with a different balance of expectation. {loser} retains every achievement already earned, while {winner} has made the pursuit meaningful again."],"pullquote":{"text":"The important distance is the distance that has just disappeared.","who":"A Gazette columnist"}},
    {"id":"s-044","situation":"comeback","edition":"season","byline":"Filed from the season review desk","standfirst":"{winnerClub} has turned a season win into a wider challenge, making the accumulated advantage of {loser} less secure.","paragraphs":["Before this campaign, the overall comparison favored {loser}. After it, the difference is smaller. Between those statements lies a substantial achievement for {winner}, whose latest season has restored an element of uncertainty to the larger competition.","The distinction matters. Winning an individual season is an honor of its own, but doing so while behind places that success in a more demanding context. {winnerClub} has not merely celebrated a result. It has improved its manager's position in the rivalry.","There is no need to declare a reversal complete. The achievement is sharper when described accurately: a deficit reduced, a contest tightened, and the future made harder to predict."],"pullquote":{"text":"An advantage is a fine thing until someone starts taking it away.","who":"The press box"}},
    {"id":"s-045","situation":"comeback","edition":"season","byline":"The Gazette's long-view report","standfirst":"The season belongs to {winner}, yet the greater news is that the Showdown no longer reads like a foregone conclusion.","paragraphs":["The temptation, when one manager opens an overall advantage, is to write the ending too early. {winner} has made that impossible for now. A season won against {loser} has brought the accumulated totals closer together.","The value of this intervention is not that it erases what came before. {loserClub} still has every earlier achievement to its credit. Rather, {winnerClub} has restored the one quality no rivalry can afford to lose: genuine uncertainty about what follows.","The Gazette can record the change without predicting the ending. An apparently settled narrative has acquired a fresh and persuasive objection."],"pullquote":{"text":"Premature conclusions are costly when the other manager still has a reply.","who":"The archive editor"}},
    {"id":"s-046","situation":"comeback","edition":"season","byline":"From the competition editor","standfirst":"{winner} has interrupted the apparent direction of the rivalry, winning this season after entering it behind on accumulated points.","paragraphs":["The overall standings had offered one reading of this Showdown: {loser} was ahead, and {winner} had work to do. The latest season has challenged that reading. A victory for {winnerClub} has made the older deficit appreciably smaller.","That alteration is significant precisely because the competition is cumulative. A strong season cannot erase the record already made, but it can challenge the course suggested by that record. {loser} remains entitled to the respect due to an earlier advantage.","The account now contains a counterargument of substance. Whatever follows, this season will be remembered as the point when the established direction was firmly questioned."],"pullquote":{"text":"A trend is not a promise, and this season has proved it.","who":"The Gazette's editorial desk"}},
    {"id":"s-047","situation":"comeback","edition":"season","byline":"From the football analysis desk","standfirst":"What had looked like {loser}'s developing advantage has met an emphatic answer, with {winner} claiming the latest season outright.","paragraphs":["Every comeback requires a result before it can become a story. {winner} has provided that result by winning the season against {loser}, having entered it behind overall. The consequence is a tighter race than the previous standings suggested.","The value of the achievement is not limited to movement in a ranking. It changes the questions asked of both managers. {loser} now has fresh competition to answer, and {winner} has a tangible reason to approach the wider contest with belief.","Nothing in the result guarantees what happens next. It does, however, remove the comfort of assuming that yesterday's advantage must dictate tomorrow's outcome."],"pullquote":{"text":"An earlier lead deserves respect, not the privilege of being permanent.","who":"The senior football correspondent"}},
    {"id":"s-048","situation":"comeback","edition":"season","byline":"An assessment from the sports desk","standfirst":"For {winner}, this was a season that could be answered with evidence, not optimism, as the challenge to {loser} gathered strength.","paragraphs":["A manager trailing in the overall contest can speak about ambition indefinitely. {winner} has done something much more persuasive: win the season. Against {loser}, that success has translated directly into a smaller accumulated shortfall.","The pleasure of a close rivalry depends partly on the quality of its opposition. {loser} had established a standard worth challenging, and {winner} has met it with a meaningful response. The latest result honors the competition as much as either manager.","For the moment, the proof belongs to {winnerClub}. Later campaigns must determine whether this season becomes a turning point or a memorable reply."],"pullquote":{"text":"Competition improves when ambition finally has something solid to show for itself.","who":"The visiting press editor"}},
    {"id":"s-049","situation":"lead-extended","edition":"season","byline":"From our chief football desk","standfirst":"The advantage has acquired another layer after {leader} claimed the season and pushed further beyond {trailer} in the overall contest.","paragraphs":["A lead can be preserved without being enlarged. {leader} has chosen the more demanding course, winning this season and adding distance between the managers in the overall standings. The latest result gives an existing advantage greater substance.","For {trailer}, the immediate disappointment lies beyond this season's verdict. A rival who already occupied the stronger position has improved it, changing the size of the task ahead. Yet the story remains a contest, not a conclusion.","The Gazette's ledger records an unmistakable shift: the front runner has gained ground. Whether that becomes decisive belongs to the remaining chapters, not this one."],"pullquote":{"text":"An advantage is worth more when its owner finds a way to enlarge it.","who":"A Gazette columnist"}},
    {"id":"s-050","situation":"lead-extended","edition":"season","byline":"An analysis from the sports editor","standfirst":"Seasonal success and overall authority have converged for {leader}, whose latest victory broadens the separation from {trailer}.","paragraphs":["Some seasons change the name at the top. This one has strengthened the name already there. By overcoming {trailer} in the seasonal comparison, {leader} has translated a fresh success into a greater overall advantage.","That distinction matters in a competition measured across separate campaigns. Every season offers its own result, but the wider reckoning remembers them together. {trailer} cannot reclaim the lost distance with an argument about reputation. Future results must do that work.","For now, the season belongs to {leader}, and so does a larger share of the overall initiative. The two judgments are closely connected, but not identical."],"pullquote":{"text":"The season is a chapter. The accumulated lead gives that chapter its weight.","who":"A Gazette columnist"}},
    {"id":"s-051","situation":"lead-extended","edition":"season","byline":"A report from the football desk","standfirst":"For {leader}, winning the season has delivered something beyond the result itself: a deeper cushion against {trailer}.","paragraphs":["Comfort in an overall lead can be deceptive, because every new season has the power to change it. {leader} has answered that uncertainty with victory, increasing the separation from {trailer} rather than relying on an advantage already earned.","This is not proof that the next contest will follow the same pattern. It is proof of what has happened to the present one. The chasing manager now confronts a wider gap, while the leader carries a stronger cumulative position.","The verdict is restrained but significant. No future outcome has been written, yet the record now gives {leader} an improved foundation from which to continue."],"pullquote":{"text":"Security in this rivalry must be earned again, not simply inherited.","who":"A Gazette columnist"}},
    {"id":"s-052","situation":"lead-extended","edition":"season","byline":"From the Gazette's editorial balcony","standfirst":"The weight of expectation has not hindered {leader}, who strengthened the overall position with a fresh seasonal triumph.","paragraphs":["Being ahead presents a question of its own: can the leading manager add to the advantage when another verdict arrives? {leader} has supplied an emphatic answer in the standings, winning the season and expanding the margin over {trailer}.","The significance is cumulative rather than theatrical. {trailer} still owns every point previously earned, and a season's result does not erase past work. It simply places a larger amount of ground between that work and the overall leader.","Expectations will adjust accordingly. This result makes {leader}'s position stronger, though no newspaper should confuse greater authority with a guarantee about what follows."],"pullquote":{"text":"A lead brings expectations. Extending it is the most convincing reply.","who":"A Gazette columnist"}},
    {"id":"s-053","situation":"lead-extended","edition":"season","byline":"From our long campaign correspondent","standfirst":"Patience has a measurable reward for {leader}, whose latest seasonal success adds another degree of separation from {trailer}.","paragraphs":["A prolonged competition asks managers to think beyond the satisfaction of a single result. This season has answered that demand in {leader}'s favor. The victory enlarges an existing overall lead and leaves {trailer} with more ground to reclaim.","It would be easy to describe this as momentum, but the standings offer something firmer than a feeling. They show an advantage genuinely extended. The next result remains unknown, and the challenger has not surrendered the right to change the picture.","For the archive, the value of this success will be apparent without embellishment. The leader began ahead, won the season, and ended further ahead still."],"pullquote":{"text":"In a long contest, adding to the lead is its own achievement.","who":"A Gazette columnist"}},
    {"id":"s-054","situation":"lead-extended","edition":"season","byline":"From the Gazette's front-page desk","standfirst":"There is no change at the summit, only a greater distance below it, after {leader} won the season.","paragraphs":["The temptation after every season is to search for an upheaval. This result offers a different kind of headline. {leader} has remained the overall front runner by winning the season and increasing the gap to {trailer}.","For the manager behind, the difficulty is not that the competition has changed its rules. The challenge is unchanged, but the distance within it has grown. That is the burden of a new loss when an earlier deficit already exists.","The story needs no invented spectacle. Its importance is visible in the standings, where the leader's advantage is now larger than before."],"pullquote":{"text":"Not every major turning point involves a change at the top.","who":"The press box"}},
    {"id":"s-055","situation":"level-overall","edition":"season","byline":"From our chief football desk","standfirst":"The latest season has brought {managerA} and {managerB} to precisely the same overall total, leaving the rivalry without a leader.","paragraphs":["There is an unusual elegance to the latest standings. After season {seasonNo}, {managerA} and {managerB} occupy matching positions in the only column that settles their running contest: the overall points total. Neither can claim an advantage.","That symmetry says nothing about whether their individual seasons followed the same course. Each manager has accumulated a separate body of work, and those different journeys now arrive at an identical figure. The rivalry is balanced, not diminished.","The page will eventually turn, but this entry deserves its own place in the archive. For now, the space between the contenders has disappeared."],"pullquote":{"text":"Different journeys can meet at a destination neither manager owns alone.","who":"A Gazette columnist"}},
    {"id":"s-056","situation":"level-overall","edition":"season","byline":"Analysis from the sporting editor","standfirst":"An apparent hierarchy has no place in the latest overall picture, with both managers sharing the same score.","paragraphs":["Rivalries invite a pecking order, a name to place above another and a familiar argument to settle. The current Showdown resists that temptation. {managerA} and {managerB} have reached exactly {points} points apiece in their overall accounts.","It is possible to admire the work of both without manufacturing a distinction between them. Their successes and setbacks belong to separate careers, yet the agreed measure of this competition gives them equal standing. That is the complete finding.","The next verdict, whenever it comes, must be earned rather than presumed. Until then, neither manager occupies the higher ground."],"pullquote":{"text":"A hierarchy looks convincing only until the evidence refuses to support it.","who":"The press box"}},
    {"id":"s-057","situation":"level-overall","edition":"season","byline":"From the back of the sports section","standfirst":"What might have been buried in the figures has become the principal story: the overall standings are level.","paragraphs":["Sometimes the most consequential detail sits at the bottom of a page. Here it deserves the largest type. The running totals for {managerA} and {managerB} are identical after the latest season, a fact that changes how the rivalry reads.","There may be more colorful ways to recount an individual campaign, but none can override the combined position. The two managers have arrived at the same measurable reward. That does not erase their differences. It gives those differences equal weight.","No dramatic embellishment is necessary. The standings have supplied a complete headline, and their restraint makes the contest feel larger rather than smaller."],"pullquote":{"text":"The smallest line of print can carry the largest consequence.","who":"The Gazette copy desk"}},
    {"id":"s-058","situation":"level-overall","edition":"season","byline":"From the Gazette archive desk","standfirst":"The competition's record offers no sole name at the top after the managers reach identical accumulated points.","paragraphs":["An archivist seeking to identify the overall leader after this season would have to leave the relevant space unfilled. {managerA} and {managerB} possess matching totals, and the evidence permits no preferred name. The record is unusually uncompromising.","Archives are often imagined as places for settled judgments, yet the best ones preserve uncertainty with equal care. This entry records a rivalry at equilibrium, with each manager's achievements remaining distinct even while their cumulative rewards agree.","There is no blank in the history itself. The absence of a single leader is precisely what gives this passage its importance."],"pullquote":{"text":"History has not misplaced a name. It has room for both.","who":"A Gazette archivist"}},
    {"id":"s-059","situation":"level-overall","edition":"season","byline":"From the editorial column","standfirst":"A shared total has turned this season's entry into a comma rather than a full stop for the rivalry.","paragraphs":["Punctuation can change the meaning of a sentence, and the latest Showdown figures offer a useful example. After season {seasonNo}, neither {managerA} nor {managerB} leads the overall contest. The present account is balanced to the point.","It would be premature to turn that equality into a verdict about either career's ultimate worth. The managers have reached the same total through separate seasons of work, and their competition deserves the patience that such a moment requires.","For now, the sentence holds open. Its meaning is not that nothing happened, but that neither rival has written the final word alone."],"pullquote":{"text":"A shared total is a comma that asks the reader to continue.","who":"A Gazette editorial writer"}},
    {"id":"s-060","situation":"level-overall","edition":"season","byline":"From the press box review","standfirst":"No separate verdict can be imposed upon an overall contest that now credits both managers with exactly {points} points.","paragraphs":["The desire for a winner is understandable, but it cannot become a substitute for the standings. Following the latest season, {managerA} and {managerB} share the same overall score. The competition recognizes no advantage between them at present.","That should not be mistaken for indecision. The measure is precise, and its outcome is straightforward. It preserves the merit of both careers without awarding either an honor that the combined evidence has not yet earned.","There is dignity in reporting the result as it stands. A great contest sometimes draws its force from the refusal to separate its protagonists."],"pullquote":{"text":"The proper verdict is the one the evidence can actually bear.","who":"The press box"}},
    {"id":"s-061","situation":"winning-streak","edition":"season","byline":"From the chief football desk","standfirst":"Another season belongs to {winner}, whose successive victories have turned an impressive run into the defining thread of this rivalry.","paragraphs":["A successful season can stand on its own. This one has joined a procession. {winner} has prevailed over {loser} again, extending a succession of season victories that now gives the contest an unmistakable shape.","The distinction matters because each campaign begins with the same opportunity to alter the story. {loserClub} remains a genuine part of that story, not merely the name beneath another result. Rivalry requires a response, and the next chapter remains unwritten.","For {winnerClub}, the achievement is continuity rather than a single flash of glory. The record now carries an expectation that the next season can either reward or overturn."],"pullquote":{"text":"A fine season earns applause. A continuing run changes the conversation.","who":"A Gazette columnist"}},
    {"id":"s-062","situation":"winning-streak","edition":"season","byline":"The Gazette football correspondent","standfirst":"With another season secured, {winner} has made consistency the most conspicuous achievement in a contest built on change.","paragraphs":["Every fresh edition offers a chance for the narrative to turn. Instead, the same manager has supplied another decisive entry. {winner} finishes this season ahead of {loser}, preserving a sequence of victories notable for its refusal to break.","There is an important difference between an enduring run and an easy rivalry. The present result establishes the former, not the latter. {loserClub} still has a separate history to write, and {winnerClub} cannot borrow anything from this season for the next.","The achievement will outlast the announcement of the points. To sustain success is to make repetition meaningful, and that is precisely what this campaign has done."],"pullquote":{"text":"Repeating the verdict is harder than merely remembering the previous one.","who":"The press box"}},
    {"id":"s-063","situation":"winning-streak","edition":"season","byline":"From our rivalry review","standfirst":"The new result gives {winner} something beyond another season victory: a body of work that survives comparison across campaigns.","paragraphs":["Sportswriting often treats every ending as a fresh revelation. Here the revelation lies in continuity. {winner} has again taken the season ahead of {loser}, and another success joins a longer, uninterrupted account.","Such a series can become shorthand for superiority, but shorthand should not obscure the competition. Each result belongs to a separate campaign, and {loserClub} remains a contender whose next opportunity is unclaimed. {winnerClub} has earned distinction, not immunity from future challenges.","The archive now has a story that stretches beyond a solitary edition. Whether it becomes a landmark or a prelude will depend on what follows."],"pullquote":{"text":"Repeated results do not erase fresh possibilities. They give those possibilities sharper edges.","who":"The Gazette archive editor"}},
    {"id":"s-064","situation":"winning-streak","edition":"season","byline":"The season results correspondent","standfirst":"For {winnerClub}, the remarkable feature is no longer a solitary success but the habit of finishing each season ahead.","paragraphs":["It is possible to celebrate a result without seeing its larger meaning. Not this time. {winner} has added another season victory over {loser}, keeping a successful sequence intact and lending fresh weight to everything that preceded it.","The latest result belongs wholly to this campaign, even as it strengthens the broader narrative. {loserClub} has been outscored in the season comparison, but it has not been written out of the competition. The next set of honours remains available to pursue.","A durable achievement asks a different question from a sudden triumph. Not simply who prevailed today, but how long excellence can continue to renew itself."],"pullquote":{"text":"A habit is only impressive when someone has to earn it again.","who":"A senior Gazette columnist"}},
    {"id":"s-065","situation":"winning-streak","edition":"season","byline":"The Touchline Gazette special report","standfirst":"With {winner} victorious again, the rivalry has acquired a recurring headline that future seasons will have to confront.","paragraphs":["What began as a series of separate decisions now reads as a continuous account of success. {winner} has taken the latest season from {loser}, ensuring the run of winning campaigns survives another turn of the calendar.","There is no need to diminish {loserClub} to appreciate that achievement. A sustained sequence makes a compelling sporting story precisely because another manager is always entitled to interrupt it. {winnerClub} has earned this entry, but must earn the next one separately.","The newspaper can print the continuation in confident type. It cannot yet print the conclusion, and that uncertainty remains the contest's most valuable asset."],"pullquote":{"text":"A recurring headline is not the same thing as a foregone conclusion.","who":"The Gazette front-page editor"}},
    {"id":"s-066","situation":"winning-streak","edition":"season","byline":"From our long-form football desk","standfirst":"An unbroken series of season victories gives {winner} a special distinction, independent of the eventual overall Showdown outcome.","paragraphs":["A rivalry can be read across more than one page. The season verdict favours {winner} again, and the latest result continues a remarkable passage of repeated successes. That is a meaningful achievement in its own right.","The final Showdown is judged on accumulated points, not simply on the appearance of successive seasonal victories. The distinction matters. Whatever the overall reckoning, {loserClub} remains a serious counterpart, while {winnerClub} can value what has already been done without claiming an ending prematurely.","The wider prize will have its own reckoning. This result, meanwhile, belongs in the account of a manager who has repeatedly met the season’s test."],"pullquote":{"text":"A sequence has its own story, even before the overall story ends.","who":"A Gazette features columnist"}},
    {"id":"s-067","situation":"final-season-decider","edition":"season","byline":"From the chief football desk","standfirst":"The contest has reached its last turning point, with {leader} ahead but the ultimate verdict still waiting for another season.","paragraphs":["There is an unusual silence at the end of this chapter. The latest season is complete, yet the result that matters most remains beyond the page. {leader} holds the overall advantage, while the final campaign still awaits.","For {trailer}, that distinction is the source of genuine opportunity. The distance between holding the lead and securing the entire Showdown is precisely what gives the approaching finale its force. Nothing has been awarded in advance.","The next season will settle the argument. Until then, the headline belongs not to a champion, but to the possibility of one."],"pullquote":{"text":"The story has a leader, but it has not found its ending.","who":"The press box"}},
    {"id":"s-068","situation":"final-season-decider","edition":"season","byline":"From our rivalry correspondent","standfirst":"For {trailer}, the approaching final season offers something more useful than consolation: an undiminished chance to shape the ending.","paragraphs":["The standings are not an obituary for the chasing manager. They are an invitation to answer back. {trailer} enters the decisive season behind {leader}, but the entire contest remains open to the result of that final campaign.","A rivalry is measured partly by how seriously its participants take one another when the balance shifts. Here, the manager in front cannot afford to dismiss the challenge, and the manager behind has every reason to embrace it.","The closing season will reveal whether the pursuit succeeds. For now, a deficit is a starting position rather than an ending."],"pullquote":{"text":"The chase matters most when the finishing line is finally in sight.","who":"The press box"}},
    {"id":"s-069","situation":"final-season-decider","edition":"season","byline":"By the Gazette's standings editor","standfirst":"The overall standings place {leader} in front, but the column that matters most has yet to receive its final entry.","paragraphs":["The figures already entered carry authority, but not finality. They record a sequence of seasons and an overall advantage for {leader}. They do not yet record a Showdown winner, because the deciding campaign remains to be contested.","For {trailer}, the unfinished ledger is a reminder that a gap can still be challenged. For the leader, it is a warning against treating the present order as permanent. Neither manager can outsource the ending to earlier results.","The last set of season points will turn a running account into a final one. Until that moment, the ledger stays open."],"pullquote":{"text":"The totals explain the past. The blank space belongs to the future.","who":"A Gazette columnist"}},
    {"id":"s-070","situation":"final-season-decider","edition":"season","byline":"From our closing stages correspondent","standfirst":"The great advantage of a final season is its clarity: both managers know exactly when the contest will be settled.","paragraphs":["The final assignment is now certain, even if its outcome remains unknown. Only the closing season stands between the managers and the Showdown verdict. {leader} begins that decisive campaign from ahead, with the overall prize unsettled.","An advantage is worth having, but it cannot perform the last task on its owner's behalf. {trailer} still has the opportunity to change the outcome, and the leader has an opportunity to preserve the position already earned.","The rivalry has reached the rare point where the next chapter is certain to be the last, yet its central answer remains unknown."],"pullquote":{"text":"The appointment is fixed. The identity of the winner is not.","who":"The press box"}},
    {"id":"s-071","situation":"final-season-decider","edition":"season","byline":"By our competition affairs writer","standfirst":"The last chance to change the standings is also the final chance for either manager to determine the overall prize.","paragraphs":["A competition can be generous with second chances until it reaches its limit. This Showdown is at that limit now. The next season will decide the prize, and no later campaign can reopen the question.","{leader} brings an advantage to the closing contest; {trailer} brings a challenge that remains legitimate until the finish. Neither position offers a shortcut through the work ahead. Their different ambitions will meet in the same decisive campaign.","What remains is not another installment of an endless contest. It is the one remaining opportunity to establish the final order."],"pullquote":{"text":"The last opportunity is not smaller. It is simply impossible to postpone.","who":"The press box"}},
    {"id":"s-072","situation":"final-season-decider","edition":"season","byline":"From the Gazette front page","standfirst":"The newspaper can report who leads today, but it must reserve its largest headline for the season still unwritten.","paragraphs":["The space where a final winner's name should appear remains deliberately empty. It is not an omission. The Showdown has reached the verge of its concluding season, and the overall prize still has no confirmed recipient.","For a paper built around this rivalry, restraint is part of the duty. {leader} deserves recognition for holding the advantage, just as {trailer} deserves recognition for remaining in contention. Neither fact cancels the other.","The definitive front page will come after the last season. For now, the honest headline is an invitation to watch what happens next."],"pullquote":{"text":"Good journalism knows when the story is not finished yet.","who":"The Gazette editorial desk"}},
    {"id":"s-073","situation":"showdown-won-1-season","edition":"final","byline":"From the chief football desk","standfirst":"The entire contest was settled in a single campaign, and {winner} has claimed a title with no return fixture.","paragraphs":["There was no long campaign in which to recover, no second chapter in which to revise the standings. {winner} has won the Showdown at its shortest distance, finishing ahead of {loser} and bringing the contest to an immediate conclusion.","That brevity gives the result a particular authority. Neither manager could rely on another season to change the meaning of this one. {winnerClub} supplied the winning return, while {loserClub} remained a worthy part of a contest decided in full.","The final account requires no footnotes about what might happen next. The competition has ended, and the name at its summit is {winner}."],"pullquote":{"text":"A short contest can still leave a long impression.","who":"A Gazette columnist"}},
    {"id":"s-074","situation":"showdown-won-1-season","edition":"final","byline":"The Gazette's season correspondent","standfirst":"{winnerClub} has delivered the decisive return in a Showdown that offered its managers just one season to separate themselves.","paragraphs":["A club can spend a whole campaign assembling its case. For {winnerClub}, that case has become the entire judgment. Under {winner}, the season produced enough points to finish above {loserClub} and secure the Showdown outright.","The significance is not that the rival's effort vanished. {loser} brought a competing season into the same frame, and that comparison gives the achievement its substance. The winning manager did not need an imagined rematch to make the outcome clear.","This edition belongs to the club whose return carried the greater weight. Its place in the Gazette's final record is secure."],"pullquote":{"text":"The club's season was the argument, and the standings delivered the answer.","who":"A Gazette columnist"}},
    {"id":"s-075","situation":"showdown-won-1-season","edition":"final","byline":"Our final standings correspondent","standfirst":"The concluding ledger shows {winner} above {loser}, with a one-season Showdown resolved by the returns already entered.","paragraphs":["On this occasion the table had no need to preserve suspense for a later edition. It could be closed at once. {winner} finished with {winnerPoints} points against {loser}'s {loserPoints}, enough to settle the entire Showdown.","Those figures represent more than a passing seasonal advantage. They are the full measure of this particular contest, because only one campaign was played. A difference in the totals became a difference between champion and runner-up without any further qualification.","The ledger is complete, although the friendly argument around it may live considerably longer. {winner} has the result that matters."],"pullquote":{"text":"There are no provisional standings when the competition itself is finished.","who":"A Gazette columnist"}},
    {"id":"s-076","situation":"showdown-won-1-season","edition":"final","byline":"The Gazette rivalry correspondent","standfirst":"For {loser}, there is no return season, but the final victory for {winner} still belongs to a shared rivalry.","paragraphs":["The record will begin with {winner}, as it must. The manager won the only season in this Showdown and therefore won the whole affair. Yet {loser} remains essential to understanding what the title means: there was an opponent to surpass.","The one-season arrangement leaves no room to turn defeat into a later recovery within this contest. It does not diminish the competing effort made by {loserClub}. Indeed, the value of {winnerClub}'s achievement comes from being measured against a real rival.","A final edition can honor the winner without diminishing the other manager. The comparison is over. The friendship behind the rivalry need not be."],"pullquote":{"text":"Every genuine victory needs a rival worthy of the comparison.","who":"A Gazette columnist"}},
    {"id":"s-077","situation":"showdown-won-1-season","edition":"final","byline":"Writing for the title review","standfirst":"Victory required no sustained reign in this format, only a superior season, and {winner} supplied exactly that.","paragraphs":["It is tempting to judge every championship by the length of the route toward it. This Showdown resists that habit. {winner} has completed the task set by a single-season competition, finishing above {loser} when the only standings were finalized.","The achievement asks to be understood on its own terms. There was no opportunity to grow an advantage through further campaigns, nor any later chance for the rival to reverse it. {winnerClub} established the difference within the agreed distance.","The resulting title is neither an installment nor an advance payment. It is the full prize, held by {winner} at the end of this edition."],"pullquote":{"text":"Measure the achievement against the challenge, not the calendar.","who":"The press box"}},
    {"id":"s-078","situation":"showdown-won-1-season","edition":"final","byline":"From our football features desk","standfirst":"Where longer Showdowns reward the patience of accumulation, this edition has rewarded {winner} for prevailing at the first opportunity.","paragraphs":["A single season does not leave much space for ambiguity. The managers made their separate claims through their clubs' returns, and the final standings placed {winner} above {loser}. With that, the entire Showdown was won.","There is a useful distinction between an abbreviated contest and an unfinished one. This was designed to stop here. {winnerClub}'s success was therefore not merely an opening advantage, and {loserClub} was not promised another campaign in which to contest it.","The prize was always intended for the manager who prevailed now. {winner} has done so, and the record can be closed without reservation."],"pullquote":{"text":"Nothing was cut short. The competition reached its intended end.","who":"The press box"}},
    {"id":"s-079","situation":"showdown-won-3-seasons","edition":"final","byline":"From the championship desk","standfirst":"The closing chapter belongs to {winner}, whose accumulated return has settled a Showdown built to be read as a trilogy.","paragraphs":["A trilogy can be remembered for its ending, but it cannot be judged without everything that came before. Across {seasonsTotal} seasons, {winner} has assembled the greater return and defeated {loser} for the Showdown title.","The result belongs to the whole sequence, not to a favorite chapter chosen afterward. Each campaign contributed to the eventual order, and {winnerClub} emerges above {loserClub} on the only measure this contest was designed to settle.","There will be other stories for these managers to write. This one has its complete beginning, middle and end, with {winner} holding the final distinction."],"pullquote":{"text":"The ending carries weight because the whole story led to it.","who":"A Gazette columnist"}},
    {"id":"s-080","situation":"showdown-won-3-seasons","edition":"final","byline":"From our rivalry correspondent","standfirst":"Victory for {winner} gives this edition its champion without diminishing the rival whose efforts helped define the contest.","paragraphs":["Finishing behind is not the same as being written out of the story. {loser} has not taken the Showdown title, but the contest with {winner} gave every season its meaning. The winner is now confirmed.","In a competition played across {seasonsTotal} seasons, an overall result emerges from comparison, not isolation. {winnerClub} finished with the stronger tally; {loserClub} supplied the opposing standard by which that achievement could be properly measured and understood.","The title belongs entirely to {winner}. The story of how a title comes to matter, however, still has room for a respected opponent and an enduring rivalry."],"pullquote":{"text":"A champion needs a result, but a rivalry gives that result meaning.","who":"The press box"}},
    {"id":"s-081","situation":"showdown-won-3-seasons","edition":"final","byline":"Our season-review editor","standfirst":"Read each campaign in isolation and the story remains unfinished. Together they make {winner}'s Showdown triumph unmistakable.","paragraphs":["The temptation after any season is to treat its conclusion as the whole tale. This contest was written differently. Only after {seasonsTotal} campaigns could its central question be answered, and the eventual champion is {winner}.","The result does not ask readers to forget the separate seasons. It asks them to read those seasons together. That broader view puts {winnerClub} above {loserClub}, giving the rivalry a conclusion that no isolated page could supply.","Now the back issues belong on the same shelf as the final edition. Their accumulated meaning is simple: {winner} has won the Showdown."],"pullquote":{"text":"No individual edition can tell the whole story of a series.","who":"A Gazette columnist"}},
    {"id":"s-082","situation":"showdown-won-3-seasons","edition":"final","byline":"From our late-edition desk","standfirst":"The final front page can now print a champion's name without qualification: {winner} has completed the winning account.","paragraphs":["A newspaper lives with unfinished stories until the evidence is complete. The Showdown has reached that point. With the agreed seasons concluded, {winner} stands above {loser}, and the championship can finally be reported as settled.","There is no need to supply imaginary scenes to lend the moment drama. The substance is already there in the competing seasons, the earned points and the fact that only the completed total decides the overall champion.","What was once an open question is now the front-page answer. The Gazette prints {winner}'s victory, and leaves the next edition to a future rivalry."],"pullquote":{"text":"The finest headline is the one the finished result can support.","who":"A Gazette editor"}},
    {"id":"s-083","situation":"showdown-won-3-seasons","edition":"final","byline":"Our correspondent on the rivalry","standfirst":"An extended sporting conversation has produced its final answer, as {winner} takes the title after the full exchange of seasons.","paragraphs":["A good rivalry has something of a correspondence about it. Each campaign places another argument on the page, and neither manager can know the final shape until the correspondence ends. Here it ends with {winner} as champion.","The exchange between {winnerClub} and {loserClub} was judged through their returns across {seasonsTotal} seasons. That shared frame gave {loser} a meaningful place in the contest even as the greater overall total eventually belonged to {winner}.","The correspondence is closed, but its pages remain worth reading. What they show together is a deserved title, earned within a rivalry neither manager could create alone."],"pullquote":{"text":"A rivalry becomes a story when both sides have something to answer.","who":"A Gazette columnist"}},
    {"id":"s-084","situation":"showdown-won-3-seasons","edition":"final","byline":"From our season perspective desk","standfirst":"The passage from opening hope to final certainty has ended with {winner} holding the prize of a completed Showdown.","paragraphs":["What feels permanent during a season can look different when another campaign is placed beside it. This Showdown allowed for that change of perspective. Once its full span was complete, {winner} had finished above {loser}.","The result is not a demand to rewrite how either manager experienced the journey. It simply sets their efforts within a larger frame. Across {seasonsTotal} seasons, {winnerClub} gained the stronger overall return and deserves the title that follows.","Memory may favor different passages of the contest. The official ending, however, is shared by every telling: {winner} is the champion of this edition."],"pullquote":{"text":"Memories may choose their favorite chapters. The championship requires the whole book.","who":"A Gazette columnist"}},
    {"id":"s-085","situation":"showdown-won-5-seasons","edition":"final","byline":"From our chief football desk","standfirst":"An extended contest has found its champion, with {winner} turning a succession of campaigns into a lasting distinction.","paragraphs":["An era is not made by its opening promise or its most memorable chapter. It is judged when the entire account closes. Across {seasonsTotal} seasons, {winner} has earned more points than {loser} and secured the Showdown.","That final distinction is larger than any isolated campaign. Both managers had the same span in which to build their case, and the accumulated results have placed {winnerClub} above {loserClub} when the contest reaches its end.","The next page belongs to memory, not prediction. What remains here is a sustained achievement, written across an era rather than snatched from a moment."],"pullquote":{"text":"An era asks for endurance, and the champion has supplied an answer.","who":"A Gazette columnist"}},
    {"id":"s-086","situation":"showdown-won-5-seasons","edition":"final","byline":"Our correspondent on the rivalry","standfirst":"The title goes to {winner}, but the length of the struggle gives this final verdict its unusual weight.","paragraphs":["Not every victory can claim the perspective that comes with distance. {winner} has defeated {loser} over {seasonsTotal} seasons, a span long enough for individual results to become parts of a much broader argument between the managers.","For {loserClub}, the final placing is not an erasure of the work recorded along the way. The rivalry needed a challenger as committed to its duration as the champion, and each campaign has helped establish the scale of the achievement.","There is no need to invent a consolation prize. The record recognizes {winnerClub} as the winning club and gives the contest itself the respect it deserves."],"pullquote":{"text":"A worthy rival is part of what makes a lasting victory worth keeping.","who":"A Gazette columnist"}},
    {"id":"s-087","situation":"showdown-won-5-seasons","edition":"final","byline":"Reporting from the closing edition","standfirst":"When the final page is filed, {winner} will own the story that mattered most across the full Showdown.","paragraphs":["Newspapers prefer a single scene, something that can be captured and framed. This championship resists that convenience. {winner} has prevailed against {loser} over {seasonsTotal} seasons, and no isolated moment can fully represent the scale of that result.","The achievement belongs to all the entries that made the final tally possible. For {winnerClub}, there is a champion's place in the Gazette. For {loserClub}, there is an equally permanent place in the story of how it was earned.","Another edition might chase a sharper image or louder revelation. This one can rely on a quieter truth: across the full span, {winner} was the better of the rivals."],"pullquote":{"text":"The photograph may capture the ending, but the article must honor the journey.","who":"The press box"}},
    {"id":"s-088","situation":"showdown-won-5-seasons","edition":"final","byline":"From the season review office","standfirst":"Consistency over a long horizon has given {winner} the final advantage, and the Showdown now belongs to the champion.","paragraphs":["The defining quality of this contest was its refusal to stop after an early judgment. Season followed season until the full {seasonsTotal} had been played. At the end of that examination, {winner} stands ahead of {loser} overall.","This does not require an invented tale of uninterrupted success. The winning case is simply the stronger total, assembled from the outcomes that counted. In a competition built on accumulation, the whole is more instructive than its individual pieces.","The distinction will survive the excitement of the announcement. {winner} has not won a promising argument about what might happen, but a completed contest about what did."],"pullquote":{"text":"The champion did not need a perfect path, only the better completed one.","who":"A Gazette columnist"}},
    {"id":"s-089","situation":"showdown-won-5-seasons","edition":"final","byline":"From the championship archive","standfirst":"A long contest can blur its smaller chapters, but the archive will be unmistakable about {winner}'s place in it.","paragraphs":["Archives are built for results that deserve more than a passing mention. {winner} has earned exactly that kind of entry, completing {seasonsTotal} seasons with a higher overall total than {loser} and taking the Showdown championship.","The folder will hold room for more than the winning name. Every campaign added something to the accumulated position, and {loser}'s contribution remains part of the record rather than disappearing beneath the final order of the managers.","Long after the excitement has cooled, the simple line will remain legible: {winner} won the contest. The years of memory may add color, not alter the result."],"pullquote":{"text":"A champion occupies the heading. A rivalry fills the pages beneath.","who":"The Gazette archivist"}},
    {"id":"s-090","situation":"showdown-won-5-seasons","edition":"final","byline":"Our correspondent on the long view","standfirst":"A championship decided across {seasonsTotal} campaigns carries a different weight, and {winner} has earned every part of that distinction.","paragraphs":["Short contests ask for instant answers. Extended ones insist on perspective. This Showdown has reached its conclusion after {seasonsTotal} seasons, and {winner} has finished with the stronger overall return against {loser}. The championship is consequently settled.","The length matters because the result could not be reduced to the first impression. Each completed campaign entered the same continuing contest, giving both managers an opportunity to add to their totals until no further chapter remained within this edition.","The verdict now has the calm of something fully tested. {winner} can enjoy the distinction without asking a future season to confirm it."],"pullquote":{"text":"A long examination deserves a result that can stand without revision.","who":"A Gazette columnist"}},
    {"id":"s-091","situation":"golden-showdown-won","edition":"final","byline":"At the history desk","standfirst":"The history books have a new first line, and it reads {winner}, who stood alone at the top of the Golden Showdown.","paragraphs":["Somewhere in the Gazette archive a page has been cleared for a name that was not there yesterday. {winner} has won the Golden Showdown, becoming the first manager to reach the line that no ordinary Showdown ever draws.","It is a rare thing for a rivalry to be remembered by its ending. Across {seasonsTotal} seasons, {winnerClub} and {loserClub} wrote the longest chapter this newspaper has known, and the final paragraph belongs to {winner}.","Future editions will refer to this one in a lowered voice. Some pages are simply bigger than the rest, and the archivist has already reached for the good paper."],"pullquote":{"text":"Every archive has one page that the others are arranged around.","who":"A Gazette archivist"}},
    {"id":"s-092","situation":"golden-showdown-won","edition":"final","byline":"From the Gazette gold desk","standfirst":"In a Showdown measured one manager at a time, {winner} has been the first to cross the golden line.","paragraphs":["This is the edition that every other edition was practice for. The Golden Showdown asks one question of each manager, and {winner} answered it before {loser} could, finishing on {winnerPoints} when {loserPoints} was the best the pursuit could manage.","There is no consolation in a race like this, only a clear order of finish. The gap of {margin} is the distance between first and second, and in a contest this long even that gap is a long way earned.","Gold is cold to the touch and warm to the memory. The Gazette prints it with pride, and the shelf at {winnerClub} has a new centrepiece."],"pullquote":{"text":"We printed a great many headlines to reach this one.","who":"A Gazette editor"}},
    {"id":"s-093","situation":"golden-showdown-won","edition":"final","byline":"Our chief writer's gold report","standfirst":"The long road is over and the gold is awarded, with {winner} first home after a Showdown that asked for everything.","paragraphs":["Nobody wins a Golden Showdown by accident. It takes patience, appetite and the nerve to keep collecting while a rival keeps pace, and {winner} had all three as {winnerClub} became the first to complete the climb.","{loser} deserves a page of its own in this story, because a chase is only as good as the pace it sets. {loserClub} set a hard one, and that is why the winning total of {winnerPoints} carries such weight.","The rivalry will go on in conversation, as the best rivalries do. For now the title is settled, and it is gold."],"pullquote":{"text":"The chase made the gold shine, and the winner made it gleam.","who":"A Gazette columnist"}},
    {"id":"s-094","situation":"golden-showdown-won","edition":"final","byline":"The Gazette's final word","standfirst":"It ends as legends end, with a name, a number it will not repeat here and a rival who made it hard.","paragraphs":["There comes a moment in every great rivalry when the story outgrows the newspaper. {winner} has won the Golden Showdown, and the Gazette, which has printed everything else, hesitates over what to add to that sentence.","Perhaps nothing at all is needed. {winnerClub} finished ahead, {loserClub} pushed it all the way, and across {seasonsTotal} seasons two managers produced a contest worth the gold that closes it.","Close the ledger gently and leave the lights on for a while. A page like this deserves a slow and thankful reading."],"pullquote":{"text":"There are headlines you write, and there are headlines that arrive.","who":"A Gazette editor"}},
    {"id":"s-095","situation":"golden-showdown-won","edition":"final","byline":"From our chief football desk","standfirst":"Gold has a way of ending arguments, and {winner} has been first to reach it, claiming the Golden Showdown for {winnerClub}.","paragraphs":["Let the presses run slowly tonight, because this edition is printed in gold. {winner} was the first manager to reach the summit of the Golden Showdown, and {loser} has no second chance to answer.","Nothing in the rules asks for a shared reckoning. A manager had to arrive first, and {winner} arrived with {loser} in close pursuit. That order of arrival is the whole story.","Historians will find {winnerClub} at the head of the roll."],"pullquote":{"text":"Gold does not share. It only goes to whoever gets there first.","who":"A Gazette columnist"}},
    {"id":"s-096","situation":"golden-showdown-won","edition":"final","byline":"Our correspondent on the dynasty","standfirst":"A dynasty is a habit that refuses to stop, and {winnerClub} under {winner} has made one worth the crown of gold.","paragraphs":["Few clubs are called a dynasty while the ink is still wet. Yet {winner} carried {winnerClub} through {seasonsTotal} seasons of steady accumulation and became the first to complete the Golden Showdown, with {loser} chasing to the end.","A dynasty is not a single glorious night. It is the quiet repetition of excellence until the rest can only watch.","{loserClub} was the rival every dynasty needs, and the pursuit was real."],"pullquote":{"text":"They did not win a night. They won an era.","who":"The dynasty desk"}},
    {"id":"s-097","situation":"showdown-drawn","edition":"final","byline":"At the final standings desk","standfirst":"The ledger closes on a perfect balance: {points} for {managerA}, {points} for {managerB} and no room for a verdict.","paragraphs":["Auditors double check a result like this, and the Gazette has done so twice. Across {seasonsTotal} seasons, {clubA} and {clubB} have produced identical totals, and the standings desk can only report that the books balance.","Mathematically this is the neatest of conclusions. In human terms it is better still, because two rivals spent years trading blows and ended up in the same place, with neither able to claim the last word.","The shared figure will sit in the archive for good. It is a single number with two owners."],"pullquote":{"text":"The numbers have said all they wish to say, and it is the same thing twice.","who":"The press box"}},
    {"id":"s-098","situation":"showdown-drawn","edition":"final","byline":"From the Gazette archive room","standfirst":"History will have to file this one under a heading it has barely used: level, together, and together at the end.","paragraphs":["Archivists like clean winners and tidy losers. This Showdown offers neither, and so {managerA} and {managerB} have earned a rarer entry, one in which both names sit on the same line with {points} beside them.","The record will show {seasonsTotal} seasons played out between {clubA} and {clubB} with nothing to separate them in the end. That is not an absence of a result. It is a result with two authors.","Future readers will open this folder expecting a champion. They will leave understanding that sometimes the champion is the contest itself."],"pullquote":{"text":"Some folders have no winner, and they are the ones people keep reading.","who":"A Gazette archivist"}},
    {"id":"s-099","situation":"showdown-drawn","edition":"final","byline":"The Gazette's final word","standfirst":"They began as rivals and they end as equals, with {managerA} and {managerB} sharing a Showdown that no one could split.","paragraphs":["The last page of the last season has been turned, and the line at the bottom reads the same for both managers. {managerA} on {points}, {managerB} on {points}, and {seasonsTotal} seasons of work between them to explain it.","It would be easy to call this an anticlimax. The Gazette prefers a different word, which is perfection, because a contest that finishes exactly even was perfectly contested from the first day to the last.","Take a bow, both of you. The newspaper has nothing left to add."],"pullquote":{"text":"The best ending was the one neither of them could have planned.","who":"A Gazette editor"}},
    {"id":"s-100","situation":"showdown-drawn","edition":"final","byline":"From our chief football desk","standfirst":"Nobody wins and nobody loses, as {managerA} and {managerB} finish the whole Showdown dead level on {points}.","paragraphs":["There are endings that crown a champion and endings that do something rarer. After {seasonsTotal} seasons, {managerA} of {clubA} and {managerB} of {clubB} stand on exactly {points} each, and the Gazette has no winner to name.","Every point earned by one manager was answered by the other, and the rivalry refused to be separated across the entire distance.","Shake hands, share the front page and keep the trophy talk for another year."],"pullquote":{"text":"A tie at the end is a compliment to both sides.","who":"A Gazette columnist"}},
    {"id":"s-101","situation":"showdown-drawn","edition":"final","byline":"Our correspondent on the rivalry","standfirst":"Two managers set out to settle an argument, and the argument has settled itself in the most surprising way.","paragraphs":["Every rivalry hopes that someone will finally be proved right. Here, {managerA} and {managerB} used {seasonsTotal} seasons to prove only that they are evenly matched, each finishing on {points}.","That is a finding of its own. {clubA} and {clubB} traded the lead, the pressure and the nerves, and neither could be shaken loose when it counted.","The argument remains open, which suits the best rivalries."],"pullquote":{"text":"Sometimes the argument ends because both sides were right all along.","who":"A Gazette columnist"}},
    {"id":"s-102","situation":"showdown-drawn","edition":"final","byline":"The late-edition desk","standfirst":"Stop the presses, then start them again, because the Showdown has ended in the one way nobody wrote a headline for.","paragraphs":["It is a little past the hour when the Gazette would usually know its champion. Instead, {managerA} and {managerB} sit level on {points}, and the final edition must find words for a night with no winner and no loser.","The pressroom has reached a happy conclusion. {clubA} and {clubB} gave the whole of {seasonsTotal} seasons everything they had, and what they had turned out to be exactly the same.","We will print it warmly and leave the headline plain. They finished together."],"pullquote":{"text":"We prepared two front pages and neither of them was this one.","who":"Overheard in the dugout"}},
    {"id":"s-103","situation":"won-on-the-final-day","edition":"final","byline":"At the final standings desk","standfirst":"Every point mattered until the last, and the last of them belonged to {winner}, who edged home by {margin}.","paragraphs":["The ledger stayed open to the end. Across {seasonsTotal} seasons the lead had never felt safe for either manager, and only the final season could say who would take the Showdown. It said {winner}, with {winnerPoints} against {loserPoints}.","A margin of {margin} sounds small written down. In a race this long it is the gap between a trophy and a long walk home, and {winnerClub} has crossed it.","Close the books and read the total once more. It will not change, however many times you look."],"pullquote":{"text":"A small margin on paper can be a very large one in the heart.","who":"The press box"}},
    {"id":"s-104","situation":"won-on-the-final-day","edition":"final","byline":"The late-edition desk","standfirst":"Hold the front page, because the Showdown was not settled until the final season, and then it was settled by {winner}.","paragraphs":["Up to the very last moment the Gazette kept two headlines ready. When the final season ended, {winner} had {winnerPoints}, {loser} had {loserPoints} and only one of the prepared pages went to print.","Close finishes are the stuff of memory. {winnerClub} will remember the nerve it took, and {loserClub} will remember how near the distance was, with only {margin} between them at the death.","Late editions are rarely so well rewarded. Tonight the wait was worth every minute."],"pullquote":{"text":"We kept two headlines ready and only one of them was needed.","who":"Overheard in the dugout"}},
    {"id":"s-105","situation":"won-on-the-final-day","edition":"final","byline":"Our chief writer's decisive report","standfirst":"Everything before it was preparation, because the final season was the one that decided who would claim the Showdown.","paragraphs":["For {seasonsTotal} seasons the contest held its breath. Then the last of them arrived, and {winner} gathered enough to pass {loser} and take the Showdown, finishing on {winnerPoints} against {loserPoints}.","It is a rare achievement to be best at the moment that matters most. {winnerClub} was exactly that, while {loserClub} gave the closing season everything it had, and left {margin} short of the line.","That is the beauty of waiting. The ending felt earned because nobody could see it coming."],"pullquote":{"text":"You cannot win a long race early, only on the last page.","who":"The press box"}},
    {"id":"s-106","situation":"won-on-the-final-day","edition":"final","byline":"The Gazette's final word","standfirst":"The longest campaign in the book has ended, and the winner of the Showdown was only known at the final turn.","paragraphs":["The Gazette has watched {seasonsTotal} seasons pass, and none of them gave away the ending. Only the last season did that, and it handed the Showdown to {winner} with {winnerPoints} on the board.","There is no shame in the chase. {loser} finished on {loserPoints}, a margin of {margin} from the prize, and the rivalry has rarely been better advertised than by that closing run.","Late glory tastes best, so we are told. Tonight {winner} is in a position to confirm it."],"pullquote":{"text":"A winner who is not sure until the end has truly won.","who":"A Gazette editor"}},
    {"id":"s-107","situation":"won-on-the-final-day","edition":"final","byline":"From our chief football desk","standfirst":"It came down to the very last season, and in the end {winner} found the answer that {loser} could not quite take away.","paragraphs":["Some Showdowns are decided early and some late. This one waited for its final season, and only then did {winner} move clear, finishing with {winnerPoints} against {loserPoints} when the book closed.","The final season carried the weight of all the others. {winnerClub} and {loserClub} had been inseparable for long stretches, and the margin of {margin} was fixed only at the last.","The final page is always the longest."],"pullquote":{"text":"The last season arrived with everything undecided, and it did not disappoint.","who":"A Gazette columnist"}},
    {"id":"s-108","situation":"won-on-the-final-day","edition":"final","byline":"Our correspondent on the rivalry","standfirst":"Never has a rivalry made so much of its final chapter, as {winner} held on when {loser} pushed hardest.","paragraphs":["There was no champion until there was nothing left to play. {loser} pressed {winner} through the closing season, and the rivalry ran to its limit before {winner} finished ahead overall.","That is the character of this contest. {winnerClub} and {loserClub} kept each other honest from the first season to the last, and the margin of {margin} is what honesty looks like in print.","The next rivalry will have to work hard to match this one."],"pullquote":{"text":"A race this tight has no winner until the very end, and no loser worth pitying.","who":"A Gazette columnist"}},
    {"id":"s-109","situation":"dominant-win","edition":"final","byline":"At the final standings desk","standfirst":"The figures speak plainly: {winner} finished on {winnerPoints} and {loser} on {loserPoints}, a gap of {margin}.","paragraphs":["Nobody needs a calculator to read this ledger. Over {seasonsTotal} seasons, {winner} built a lead that stretched to {margin} by the end, and the Showdown belongs to {winnerClub} by a wide and comfortable distance.","Wide margins are not always won in a rush. This one was assembled steadily, one good season after another, until the gap simply became too large for anyone to close.","The totals are filed and the verdict is clear. Let the champion enjoy it."],"pullquote":{"text":"A margin like this is written in pencil first and ink later.","who":"The press box"}},
    {"id":"s-110","situation":"dominant-win","edition":"final","byline":"From the Gazette gold desk","standfirst":"Pick up the cabinet key, because {winnerClub} is going to need the whole shelf after a Showdown this commanding.","paragraphs":["There is a particular sound a trophy makes when it is set down with confidence. {winner} has finished {seasonsTotal} seasons so far ahead of {loser} that the Showdown felt decided long before the final page.","The tally of {winnerPoints} points, {loserPoints} for the rival and a margin of {margin} between them. Those are the figures a champion dreams of, and {winnerClub} has the evidence in black and white.","A win this big is a memory the whole club can share."],"pullquote":{"text":"Some wins sneak up on you, and others walk in through the front door.","who":"Overheard in the dugout"}},
    {"id":"s-111","situation":"dominant-win","edition":"final","byline":"From the club desk","standfirst":"Down at {winnerClub} the mood is quietly regal, and the Showdown trophy has found a home it intends to keep.","paragraphs":["A comfortable victory is a different animal from a narrow one. {winner} has won the Showdown by {margin}, and the sense around {winnerClub} is of a job done thoroughly rather than a battle narrowly survived.","{loser} and {loserClub} carry on with their own plans, and a dominant finish for a rival does not close the book on them. It simply tells them where the standard now sits.","The winning club can now enjoy the calm of a decision that nobody doubts."],"pullquote":{"text":"A comfortable win is a thousand small good decisions in a row.","who":"The tea lady at the training ground"}},
    {"id":"s-112","situation":"dominant-win","edition":"final","byline":"The Gazette's final word","standfirst":"The Showdown is over, and the verdict is a wide and happy one for {winner}, who led for most of the way.","paragraphs":["The Gazette records, with pleasure, that {winner} has won the Showdown by a distance. With {winnerPoints} against {loserPoints}, the gap of {margin} makes the story a short one to tell.","Brevity is no insult here. The shortest headlines belong to the biggest wins, and {winnerClub} has earned a front page that does not need a second line to explain itself.","Well played, both of you. One of you simply played a little better."],"pullquote":{"text":"A great win needs no footnote and no explanation.","who":"A Gazette editor"}},
    {"id":"s-113","situation":"dominant-win","edition":"final","byline":"From our chief football desk","standfirst":"It was never close in the end, as {winner} finished the Showdown far ahead of {loser} with {winnerPoints} to the rival's {loserPoints}.","paragraphs":["Some Showdowns are a contest and some are a coronation. This one began as the first and finished as the second, with {winner} ending {seasonsTotal} seasons well beyond reach.","The margin of {margin} tells the tale in a single figure. {winnerClub} did not so much win the Showdown as take possession of it.","Dominance is rarer than talent, and harder to keep. {winner} kept it throughout."],"pullquote":{"text":"Winning is one thing. This was something closer to ownership.","who":"A Gazette columnist"}},
    {"id":"s-114","situation":"dominant-win","edition":"final","byline":"Our correspondent on the rivalry","standfirst":"A rivalry sometimes finds a manager operating on a different level, and here that manager was {winner}.","paragraphs":["Rivalries thrive on balance, but this one tilted early and kept tilting. {winner} finished {margin} clear of {loser}, giving {winnerClub} an undisputed claim on the title.","{loserClub} deserves credit for staying in the contest. Pursuing a leader this far ahead takes character, and {loser} kept coming even when the horizon grew distant.","Next time the scales may swing the other way. That is how rivalries stay alive."],"pullquote":{"text":"The best rivals push the champion to look even better.","who":"A Gazette columnist"}}
  ]);
  const DUETS=freeze([
    {"id":"d-0001","situation":"big-win","lead":"{winner} takes the season by miles and {loser} is left waving from the back of the pack.","co":"Waving is generous. At that distance {loserClub} needed binoculars just to find the leader."},
    {"id":"d-0002","situation":"big-win","lead":"The gap is opening and {winner} is already out of sight over the horizon.","co":"And {loserClub} are still reading the map. Once {winnerClub} found their rhythm there was no way in."},
    {"id":"d-0003","situation":"big-win","lead":"{margin} clear at the finish and {loser} is still asking where it all went wrong.","co":"Nowhere in particular. It was a steady march with no wobbles, so there was nothing to chase."},
    {"id":"d-0004","situation":"big-win","lead":"This was less a race and more a stampede, with {winner} doing the trampling.","co":"Then {loser} did well to stay on their feet. Most rivals would have been flattened by Christmas."},
    {"id":"d-0005","situation":"big-win","lead":"{winnerClub} were ruthless from first week to last while {loser} picked up the pieces.","co":"Ruthless but never reckless. A gap this size takes a manager who simply refuses to ease off."},
    {"id":"d-0006","situation":"big-win","lead":"There is no way back for {loser} this time, and everyone in the room knows it.","co":"True, but notice how calm {loser} looks. A lead like this is exactly what makes next season dangerous."},
    {"id":"d-0007","situation":"big-win","lead":"Foot flat on the floor, {winner} watched the gap stretch season long.","co":"And {loserClub} ran out of road long before the finish, which is a hard lesson to swallow."},
    {"id":"d-0008","situation":"big-win","lead":"Nobody else is in this conversation now, because {winner} has taken the lot.","co":"It is the kind of season managers frame and hang in the hallway for the grandchildren."},
    {"id":"d-0009","situation":"big-win","lead":"Send the camera crew to {loserClub}, because that is a very long walk home.","co":"The only mercy is the scenery. {winnerClub} never looked back, so nobody saw the walk begin."},
    {"id":"d-0010","situation":"big-win","lead":"A proper hiding in the table, and {winner} dished it out week after week.","co":"Dominant from first to last. {loser} did nothing wrong and still ended up a county behind."},
    {"id":"d-0011","situation":"big-win","lead":"{loser} turned up full of hope and {winner} quietly took it away.","co":"Quietly is the key word. There was no gloating, just a lead that grew every week."},
    {"id":"d-0012","situation":"big-win","lead":"{margin} clear stops being a battle and becomes a lecture, with {winner} at the lectern.","co":"A lecture needs questions from the floor, and {loser} has been far too stunned to raise a hand."},
    {"id":"d-0013","situation":"comfortable-win","lead":"{winner} wins the season by {margin} and makes it look like a Sunday stroll.","co":"The best managers make hard things look dull. This was control from start to finish, with no sprint needed."},
    {"id":"d-0014","situation":"comfortable-win","lead":"Sealed with a little to spare, and {winner} sails past {loser} by {margin}.","co":"Comfortable but not crushing, which is exactly how a margin like that ought to feel."},
    {"id":"d-0015","situation":"comfortable-win","lead":"No thrashing here, only a steady grip from {winner} that {loser} could never loosen.","co":"Grips like that start with a plan, and {winnerClub} clearly had one from the opening week."},
    {"id":"d-0016","situation":"comfortable-win","lead":"While {loserClub} began to rattle, {winnerClub} simply kept their heads, and that wins races.","co":"Panic is the enemy of any lead. {winner} kept it at arm's length all year."},
    {"id":"d-0017","situation":"comfortable-win","lead":"A {margin}-point cushion is a healthy place to be, and {winner} is spending it wisely.","co":"A cushion only helps if you sit on it properly, and {winner} clearly knows how to sit."},
    {"id":"d-0018","situation":"comfortable-win","lead":"Not a single firework from {winner}, just quiet efficiency that leaves {loser} fuming.","co":"Efficiency gets no applause but it gets points, and that is why the table looks this way."},
    {"id":"d-0019","situation":"comfortable-win","lead":"{loser} made a proper fight of it for a spell, but {winner} always had an answer.","co":"Having another answer ready is what separates a champion from a contender."},
    {"id":"d-0020","situation":"comfortable-win","lead":"{loserClub} wobbled and {winnerClub} did not, and that is most of the story.","co":"Every wobble costs ground, and {winner} guarded every inch of theirs."},
    {"id":"d-0021","situation":"comfortable-win","lead":"Setting the pace early meant {winner} never had to chase anything down.","co":"Setting it is easy. Holding it for a whole season takes real discipline."},
    {"id":"d-0022","situation":"comfortable-win","lead":"{margin} clear and a sensible finish, so {loser} has little to argue with.","co":"Sensible wins are still wins, and {winnerClub} collected theirs without any fuss."},
    {"id":"d-0023","situation":"comfortable-win","lead":"I suspect {loser} would swap that {margin} for a re-run of a few key weeks.","co":"Who wouldn't? {winnerClub} punished every slip, and the slips added up to a gap."},
    {"id":"d-0024","situation":"comfortable-win","lead":"Under pressure, {winner} stayed composed, and that was the whole difference.","co":"Pressure shows you who people really are. {winner} showed calm when it counted."},
    {"id":"d-0025","situation":"narrow-win","lead":"{winner} edges {loser} by {margin} and nobody in the room is breathing easy.","co":"One slip would have flipped the whole thing, and neither manager gave an inch."},
    {"id":"d-0026","situation":"narrow-win","lead":"The slimmest of margins, and {winner} gets the nod by {margin}.","co":"Slim wins still go in the book. Nobody asks how thin they were in ten years."},
    {"id":"d-0027","situation":"narrow-win","lead":"You could slide a pin between {winnerClub} and {loserClub} right now.","co":"A pin's width is still a width, and {winner} landed on the right side of it."},
    {"id":"d-0028","situation":"narrow-win","lead":"Who blinks first? {winner} did not, and that is the entire difference.","co":"Nerves decide contests like this, and {loser} let theirs show a moment too soon."},
    {"id":"d-0029","situation":"narrow-win","lead":"Nail-biting from start to finish, and {winner} comes out on top by a whisker.","co":"Whiskers matter. The lead swapped hands plenty, but {winner} held it when it counted."},
    {"id":"d-0030","situation":"narrow-win","lead":"{loser} will be sick about this one because the prize was right there to take.","co":"Taking is the hard part, and {loserClub} watched it slide just out of reach."},
    {"id":"d-0031","situation":"narrow-win","lead":"Only {margin} separates them, and that is all the drama this result needed.","co":"Drama comes cheap when it is this fine, and both managers earned every ounce of it."},
    {"id":"d-0032","situation":"narrow-win","lead":"A narrow win for {winner} means an even narrower loss for {loserClub}.","co":"Narrow losses sting longest, because the fix always seems to be one small step away."},
    {"id":"d-0033","situation":"narrow-win","lead":"Whisker thin, that is the phrase, and {winner} walks away smiling.","co":"Smiles are earned in the squeakers, and {winnerClub} earned this one fair and square."},
    {"id":"d-0034","situation":"narrow-win","lead":"Somebody should tell {loser} just how fine that line was, though it hardly helps.","co":"Fine is only a feeling until it is locked in, and now it is a result for {winner}."},
    {"id":"d-0035","situation":"narrow-win","lead":"{loserClub} had their hands on it, and then the lead slipped away by {margin}.","co":"Hands on a prize are not the same as holding it, and {winnerClub} held on hard."},
    {"id":"d-0036","situation":"narrow-win","lead":"Inches decided it, and every one of them belonged to {winner}.","co":"Inches are where these battles are won, and {winner} measured each one carefully."},
    {"id":"d-0037","situation":"draw","lead":"All square at the close, with {managerA} and {managerB} both on {points}.","co":"Nobody dropped off at any stage, so this is a fair split rather than a verdict."},
    {"id":"d-0038","situation":"draw","lead":"{clubA} and {clubB} land on identical totals, and the rivalry rolls on undecided.","co":"Undecided is the honest word. Neither club found the gap that would have settled it."},
    {"id":"d-0039","situation":"draw","lead":"Consistency was meant to pay, yet it has only bought {managerA} and {managerB} a share.","co":"Nobody slipped, so the gap never opened and the books close on {points} apiece."},
    {"id":"d-0040","situation":"draw","lead":"Nobody is celebrating at {clubA} or {clubB}, because parity is a strange sort of prize.","co":"A fine outcome in theory, but it sits badly with anyone who came to win outright."},
    {"id":"d-0041","situation":"draw","lead":"The final tally reads {points} apiece, and no verdict beyond that is coming.","co":"Fair enough. Neither manager handed the other a single moment to edge clear."},
    {"id":"d-0042","situation":"draw","lead":"Not a winner and not a loser, just two bosses on exactly equal footing.","co":"In a Showdown that counts for something, because nobody let the other run away."},
    {"id":"d-0043","situation":"draw","lead":"Nobody could separate {managerA} from {managerB}, and the season tells the same tale.","co":"On paper they are twins, and the way they traded blows all year backs that up."},
    {"id":"d-0044","situation":"draw","lead":"No gap ever opened between {clubA} and {clubB}, so the books close with nothing to pick apart.","co":"Both kept pace from the first whistle to the last, which makes this a stalemate of equals."},
    {"id":"d-0045","situation":"draw","lead":"Bragging rights stay locked in the drawer, as {managerA} and {managerB} finished level.","co":"Expect a long argument in both camps about who had the better year, and neither can win it."},
    {"id":"d-0046","situation":"draw","lead":"A stalemate at the top, and neither boss will be gracious about sharing it.","co":"Gracious may be a stretch, but a clean finish with nothing hidden is something both can respect."},
    {"id":"d-0047","situation":"draw","lead":"Every good grudge needs a spell like this, where nobody may claim domination.","co":"Domination is a myth here. The points never gave either side room to breathe."},
    {"id":"d-0048","situation":"draw","lead":"Supporters of {clubA} and {clubB} both trudge home certain they were the better outfit.","co":"Each camp swears it was superior, and that argument is half the fun of a rivalry."},
    {"id":"d-0049","situation":"champions-league","lead":"{winner} lifts the Champions League and {loserClub} are left staring at an empty plinth.","co":"The grandest prize in club football, and nothing else on the card comes close."},
    {"id":"d-0050","situation":"champions-league","lead":"Continental glory for {winnerClub}, as {winner} claims the title no one else could reach.","co":"Years of building went into this moment, and the silverware finally answers the question."},
    {"id":"d-0051","situation":"champions-league","lead":"{winner} takes the biggest gong in club football, and the cabinet gets a new centrepiece.","co":"Every manager wants that one on the shelf, and this arrival changes the whole picture."},
    {"id":"d-0052","situation":"champions-league","lead":"A long wait ends for {winner}, with the continental crown finally in their hands.","co":"Patience is the word. The wait was longer than most managers would tolerate."},
    {"id":"d-0053","situation":"champions-league","lead":"{winnerClub} have taken Europe's grandest crown, and {loserClub} can only nod along.","co":"Respect where it is due. A prize like that goes only to sides who keep coming back."},
    {"id":"d-0054","situation":"champions-league","lead":"{winner} clears {loser} by {margin}, and the main European honour is in the bag.","co":"A gap that size settles the argument, and the trophy only makes it sweeter."},
    {"id":"d-0055","situation":"champions-league","lead":"The Champions League belongs to {winner}, and {margin} now separates the rivals.","co":"That is a rare kind of separation, and the chasing side will need a huge response."},
    {"id":"d-0056","situation":"champions-league","lead":"Champions League success for {winnerClub} has reshaped the top of the standings entirely.","co":"The trophy counts for so much that the points on top are merely a bonus."},
    {"id":"d-0057","situation":"champions-league","lead":"{loser} had their moments, but the crown went the other way.","co":"Moments only count for so much, and {loser} knows that better than anyone."},
    {"id":"d-0058","situation":"champions-league","lead":"A dream season for {winnerClub}, and the title belongs to {winner} now.","co":"Dreams are the right word, because this one rewards a long and patient campaign."},
    {"id":"d-0059","situation":"champions-league","lead":"{loserClub} will remember this one for ages, since the crown went elsewhere.","co":"Grief is natural, but good sportsmanship will carry {loser} past the sore bit."},
    {"id":"d-0060","situation":"champions-league","lead":"Europe's prize room has a new name on the wall, and it reads {winner}.","co":"It is a name people will read on the honours board for years, and it looks right there."},
    {"id":"d-0061","situation":"europa-league","lead":"{winner} lifts the Europa League and {loserClub} are left to console themselves.","co":"A pot is a pot, and the cabinet never asks which stage it came from."},
    {"id":"d-0062","situation":"europa-league","lead":"Nobody expected {winnerClub} to go this far, and now {winner} holds the continental prize.","co":"The best runs always begin with nobody believing in them, and this one ended with a trophy."},
    {"id":"d-0063","situation":"europa-league","lead":"{winner} wins the cup and pulls clear in the standings by {margin} points.","co":"A tidy margin for a tidy result, and nobody can say the silverware was handed over."},
    {"id":"d-0064","situation":"europa-league","lead":"European glory for {winnerClub}, and {winner} gets to hoist the silverware.","co":"Hoisting is the best bit. Those photos stay in the club archive for years."},
    {"id":"d-0065","situation":"europa-league","lead":"The continental gong goes to {winner}, and the name goes up in lights.","co":"Lights or no lights, the name on the trophy is what supporters remember."},
    {"id":"d-0066","situation":"europa-league","lead":"{loser} came so close to the continental prize, and {winner} took it on the day.","co":"Close is no use in a Showdown, and the difference was in the decisive moments."},
    {"id":"d-0067","situation":"europa-league","lead":"{winner} holds the cup, and a gap of {margin} points opens up at the top.","co":"Gaps open fast when a manager finds form, and the rest must find an answer."},
    {"id":"d-0068","situation":"europa-league","lead":"A European crown for {winnerClub}, and {margin} now separates the rivals.","co":"That feels huge, but a Showdown is long enough for the chasing side to come back."},
    {"id":"d-0069","situation":"europa-league","lead":"The Europa League is {winner}'s, and {loser} can only tip their hat.","co":"A tip of the hat is fitting, because the run was good and deserved a bow."},
    {"id":"d-0070","situation":"europa-league","lead":"{loserClub} will rue the moment the continental prize slipped out of reach.","co":"Rueing is natural, but the club returns to the table with a sharper plan."},
    {"id":"d-0071","situation":"europa-league","lead":"{winnerClub} now carry a European title into the coming campaign.","co":"Carrying silverware is a fine way to start, and it sends a message to the field."},
    {"id":"d-0072","situation":"europa-league","lead":"The European gong goes to {winner}, and the mood in {winnerClub}'s camp is electric.","co":"Electric is the perfect word. A gong of that stature lifts the whole group and staff."},
    {"id":"d-0073","situation":"league-title","lead":"{winnerClub} have it wrapped up, and nobody is really surprised.","co":"Steady from the opening week to the last, which is exactly how big prizes get won."},
    {"id":"d-0074","situation":"league-title","lead":"The trophy heads to {winnerClub}, and the table has stopped pretending.","co":"The summit is built one unglamorous decision at a time, and {winnerClub} made the right ones."},
    {"id":"d-0075","situation":"league-title","lead":"Cups reward a big night, but the league rewards patience, and {winner} had plenty.","co":"Being good for that long is harder than one great moment, and it counts for more."},
    {"id":"d-0076","situation":"league-title","lead":"Early on {loser} had their moments, but the chase belonged to {winner} all along.","co":"Leaders who wobble in the middle end up watching the standings from behind."},
    {"id":"d-0077","situation":"league-title","lead":"The honours are sealed for {winnerClub}, and the standings have finally settled down.","co":"They were never shaken off the summit, and that steadiness made all the difference."},
    {"id":"d-0078","situation":"league-title","lead":"Sprints win cups, but a league is a marathon, and {winner} has finished it.","co":"Staying in contention from start to finish is the real skill, and {winner} has it."},
    {"id":"d-0079","situation":"league-title","lead":"{loser} can only watch the standings now as {winner} lifts the trophy.","co":"One bad spell in the middle is hard to climb out of, and nobody catches up after it."},
    {"id":"d-0080","situation":"league-title","lead":"The gold goes to {winnerClub}, and it arrives without any fuss at all.","co":"Quiet, disciplined football rarely makes the noise, but it does collect the silverware."},
    {"id":"d-0081","situation":"league-title","lead":"That settles it. {winner} is the champion and the rest are chasing shadows.","co":"Over a long stretch, calm nerves are worth more than one flashy streak of form."},
    {"id":"d-0082","situation":"league-title","lead":"Champions again in the record books, and {winnerClub} have room for one more gleaming piece.","co":"Honours are won in the quiet weeks, when nobody is watching and every choice still counts."},
    {"id":"d-0083","situation":"league-title","lead":"A championship for {winner}, and the finish looks almost too easy from the stands.","co":"Easy from the sofa, maybe. Every decision along the way had to be right."},
    {"id":"d-0084","situation":"league-title","lead":"Champions of the land are {winnerClub}, and they have every right to strut a little.","co":"Strutting is allowed once you have done the hard yards across a full campaign."},
    {"id":"d-0085","situation":"cup-double","lead":"{winnerClub} hold the title and the domestic cup, the whole set in one season.","co":"One trophy is a fine return, but landing the full set is something else entirely."},
    {"id":"d-0086","situation":"cup-double","lead":"Both prizes in one season, and {winner} makes it look like the easy route.","co":"Easy it is not. Plenty of managers go years without getting both in one year."},
    {"id":"d-0087","situation":"cup-double","lead":"Only a handful of managers pull off the double, and {winnerClub} have just joined them.","co":"A rare blend of steadiness and sharpness, and it deserves every bit of applause."},
    {"id":"d-0088","situation":"cup-double","lead":"{loser} collected a fine prize this time, but {winner} went and took the lot.","co":"Taking it all needs nerve in every competition, and a dash of good fortune too."},
    {"id":"d-0089","situation":"cup-double","lead":"A pair of trophies in one campaign, and {winnerClub} are beaming.","co":"Pairs are rare because the table demands consistency while the cup demands a cool head."},
    {"id":"d-0090","situation":"cup-double","lead":"The table says {winnerClub} were the steadiest, and the cup run agrees.","co":"When the standings and the trophies point the same way, there is only one story."},
    {"id":"d-0091","situation":"cup-double","lead":"Having taken the title, {winnerClub} refused to stop and lifted the cup as well.","co":"Stopping would have been sensible, but ambition is stubborn and so is {winner}."},
    {"id":"d-0092","situation":"cup-double","lead":"A title and a cup for {winner}, and the cabinet needs a rethink.","co":"A haul like that turns the trophy room into the most crowded room at the club."},
    {"id":"d-0093","situation":"cup-double","lead":"Watch out for {winner}, because the set is complete and the rest are scrambling.","co":"When one manager is strong on every front, the chasers run out of places to hide."},
    {"id":"d-0094","situation":"cup-double","lead":"The set is complete for {winnerClub}, and the cheers carry to the far end of the table.","co":"The cheers are fair. A league asks for patience and a cup final asks for nerve."},
    {"id":"d-0095","situation":"cup-double","lead":"Rare air for {winner}, with title form and a cup win in the same breath.","co":"Few managers combine steady table form with cup grit, and {winner} managed both."},
    {"id":"d-0096","situation":"cup-double","lead":"Another name joins the exclusive club, and this time it is {winnerClub}.","co":"The club is small and selective, and {winnerClub} earned the invitation the hard way."},
    {"id":"d-0097","situation":"no-trophy","lead":"{winnerClub} took the season with empty hands and topped the ladder anyway.","co":"Small gains and sound form carry a club a long way when the display case stays bare."},
    {"id":"d-0098","situation":"no-trophy","lead":"Not a piece of silverware in sight, yet {winner} sits ahead of {loser}.","co":"Points need no shiny object to count. They only need to keep arriving."},
    {"id":"d-0099","situation":"no-trophy","lead":"Nothing for the mantelpiece at {winnerClub}, but plenty for the standings.","co":"Small gains are a quiet kind of reward, and they add up without any fanfare."},
    {"id":"d-0100","situation":"no-trophy","lead":"A bare shelf for {winner}, yet the running tally looks very healthy indeed.","co":"Bonuses do not shout, but they stack up nicely when nobody is paying attention."},
    {"id":"d-0101","situation":"no-trophy","lead":"No gongs this time for {winnerClub}, and the standings could not care less.","co":"Consistency is a prize of its own in a long contest, and it quietly builds the tally."},
    {"id":"d-0102","situation":"no-trophy","lead":"The shelves stay empty for {winner}, and still the tally keeps climbing.","co":"Everything banked from bonuses is real, and it never needs a display case."},
    {"id":"d-0103","situation":"no-trophy","lead":"{loser} chased the glamour the whole way while {winner} collected the small change.","co":"Silverware looks glamorous, but a steady flow of extras is what kept {winner} in front."},
    {"id":"d-0104","situation":"no-trophy","lead":"Without a single medal on the mantelpiece, {winnerClub} still come out on top.","co":"Medals are lovely, but steady returns win seasons too, and that is today's lesson."},
    {"id":"d-0105","situation":"no-trophy","lead":"The silverware went elsewhere, but the extra credit came home to {winnerClub}.","co":"A season with no trophy can still be a winning one, and this proves it."},
    {"id":"d-0106","situation":"no-trophy","lead":"An empty display case for {winner}, and a full notebook of good results.","co":"Steadiness without a cup in sight is still steadiness, and it goes on the record."},
    {"id":"d-0107","situation":"no-trophy","lead":"A modest triumph for {winnerClub}, with nothing lifted and no fuss made.","co":"Modest triumphs get no parade, but they land in the total, and the total is what matters."},
    {"id":"d-0108","situation":"no-trophy","lead":"Hard to believe a season can be claimed without hardware, yet {winner} has done it.","co":"It takes sound form, a careful hunt for extras and a little nerve to pull it off."},
    {"id":"d-0109","situation":"comeback","lead":"Behind at the start of season {seasonNo}, but {winner} has torn the gap up.","co":"Patience is the quiet weapon. {winner} waited for the seasons that mattered, then took them."},
    {"id":"d-0110","situation":"comeback","lead":"They wrote {winner} off on points, and nobody thought to tell {winner}.","co":"Chasers look harmless until the leader glances round and finds them already past."},
    {"id":"d-0111","situation":"comeback","lead":"{winner} trailed badly once, and now the whole picture has flipped.","co":"A flip this big is rarely one season's work. It is quiet results adding up."},
    {"id":"d-0112","situation":"comeback","lead":"{loser} was lounging at the top, and {winner} came through the middle without a sound.","co":"Silence is a hunter's best friend. A leader only hears footsteps when they are close."},
    {"id":"d-0113","situation":"comeback","lead":"A poor spell had {winner} sinking, then {winnerPoints} to {loserPoints} turned the whole thing round.","co":"One good season does not erase the bad ones, but it can outweigh them in a single go."},
    {"id":"d-0114","situation":"comeback","lead":"{loser} thought the lead was comfortable, then {winner} turned up unannounced.","co":"Comfortable leads attract visitors, and {loser} has just met the unwelcome sort."},
    {"id":"d-0115","situation":"comeback","lead":"Politeness is over, as {winner} has made the Showdown a proper fight again.","co":"Chasers who wait for permission never catch anybody, and {winner} stopped asking long ago."},
    {"id":"d-0116","situation":"comeback","lead":"They said the race was finished, and {winner} simply carried on training.","co":"Being written off is just a head start for the chaser who kept sharpening."},
    {"id":"d-0117","situation":"comeback","lead":"Look at the table, because the gap has gone and {winner} is the one who ate it.","co":"Gaps never close on their own. Somebody has to keep biting away, season after season."},
    {"id":"d-0118","situation":"comeback","lead":"Chasing from the start, now {winner} finally catches {loser} overall.","co":"Anyone can lead for a season. Catching the leader takes grit that nobody applauds."},
    {"id":"d-0119","situation":"comeback","lead":"A quiet recovery, and suddenly {winner} is the one the whole room is watching.","co":"The best comebacks look dull in the middle, which is why nobody saw this one coming."},
    {"id":"d-0120","situation":"comeback","lead":"Trailing {loser} before season {seasonNo}, and the lead belongs to {winner} at last.","co":"Turning points never announce themselves, but {winner} spotted this one early."},
    {"id":"d-0121","situation":"lead-extended","lead":"{leader} wins again and pulls clear of {trailer}, and the rear view is emptying.","co":"An empty mirror is the leader's favourite sight, and {trailer} knows exactly what it means."},
    {"id":"d-0122","situation":"lead-extended","lead":"Another win for {leader}, and {trailer} has to stop and count the cost.","co":"The cost is the seasons already gone, and no single one can buy them back."},
    {"id":"d-0123","situation":"lead-extended","lead":"Taking the season, {leader} stretches the overall lead to {margin} clear.","co":"The bigger the cushion, the more a leader can afford to play it steady from here."},
    {"id":"d-0124","situation":"lead-extended","lead":"{trailer} needed this one badly, and {leader} took it without breaking stride.","co":"Hunger is a fine thing, but good form on the other side will outrun it."},
    {"id":"d-0125","situation":"lead-extended","lead":"The Showdown looks one-sided with {leader} out front, and {trailer} knows it.","co":"One-sided is fair, and {trailer} has spent a long while on the wrong end of it."},
    {"id":"d-0126","situation":"lead-extended","lead":"Season after season {leader} keeps stacking wins, and {trailer} is running short of options.","co":"Stack enough victories and the rest of the field starts to look like spectators."},
    {"id":"d-0127","situation":"lead-extended","lead":"Bonus points keep landing for {leader}, and {trailer} is still waiting for a turn.","co":"Little extras build up over a long Showdown, and {leader} has collected them all along."},
    {"id":"d-0128","situation":"lead-extended","lead":"Another Champions League for {leader}, and the chase has turned into a climb.","co":"A trophy of that size moves the needle, and distance like that does not close quickly."},
    {"id":"d-0129","situation":"lead-extended","lead":"A cup joins the cabinet at {leader}, and {trailer} watches the gap grow.","co":"Cabinets fill slowly, but every trophy is another brick in the wall between the two."},
    {"id":"d-0130","situation":"lead-extended","lead":"Help must come from somewhere for {trailer}, and {leader} is not waiting around.","co":"Hope is no plan, and {trailer} needs wins that {leader} is busy taking."},
    {"id":"d-0131","situation":"lead-extended","lead":"Europa League glory for {leader}, and the margin edges out again.","co":"Any trophy counts for more when you are already in front, and {leader} knows it."},
    {"id":"d-0132","situation":"lead-extended","lead":"Stuck in the middle ground, {trailer} watches {leader} sit at the top.","co":"The middle is cruel. Too close to the top to relax, too far off to threaten."},
    {"id":"d-0133","situation":"level-overall","lead":"Dead level on {points}, {managerA} and {managerB} are waiting for the other to flinch.","co":"A standoff between careful managers, and whoever moves first gives away the advantage."},
    {"id":"d-0134","situation":"level-overall","lead":"Season {seasonNo} ends with {clubA} and {clubB} side by side on {points}.","co":"Level is a fair result, though neither club will enjoy sharing it."},
    {"id":"d-0135","situation":"level-overall","lead":"Over {seasonsTotal} seasons these two have traded blows, and now the totals match.","co":"Traded blows across the whole run and still neither has pulled ahead, which is a credit to both."},
    {"id":"d-0136","situation":"level-overall","lead":"The overall stands even at {points}, and the table has never looked so balanced.","co":"Balance like that is rare. It takes two managers at the same standard for this long."},
    {"id":"d-0137","situation":"level-overall","lead":"Having swapped the top spot, {clubA} and {clubB} now share it on {points}.","co":"Sharing the top is a nice problem, but the next season will not let it stay shared."},
    {"id":"d-0138","situation":"level-overall","lead":"Mirror images, the pair of them, matching on {points} with nothing to split them.","co":"Nothing but who blinks first, and neither manager is the blinking sort."},
    {"id":"d-0139","situation":"level-overall","lead":"Both sides finish season {seasonNo} on {points}, and the scales sit perfectly still.","co":"Scales that never move are rare. It takes two steady managers to keep them that way."},
    {"id":"d-0140","situation":"level-overall","lead":"Shoulder to shoulder after season {seasonNo}, {managerA} and {managerB} look at each other and grin.","co":"A grin from each camp means the rivalry is doing exactly what it should."},
    {"id":"d-0141","situation":"level-overall","lead":"A dead heat after {seasonsTotal} seasons, and the friendly needle is already back.","co":"Dead heats make the best rivalries. Nobody gets to gloat and nobody gets to sulk."},
    {"id":"d-0142","situation":"level-overall","lead":"{managerA} calls it a fair result, while {managerB} calls it a warning.","co":"Both are right, because a shared total only feels fair until the next season begins."},
    {"id":"d-0143","situation":"level-overall","lead":"The totals are identical on {points}, and both clubs are hunting for a way out.","co":"A deadlock this clean needs one good season to break, and it could come from either side."},
    {"id":"d-0144","situation":"level-overall","lead":"For {seasonsTotal} seasons {clubA} and {clubB} have matched each other, and they are still going.","co":"Matching each other that long is no accident. It is two sides refusing to flinch."},
    {"id":"d-0145","situation":"winning-streak","lead":"{loser} hoped this would finally be the season of change.","co":"Change needs a plan that works, and right now {winner} is the only one holding one."},
    {"id":"d-0146","situation":"winning-streak","lead":"Let us be honest. {winner} has become the benchmark everyone else gets measured against.","co":"And the chasers are all aiming at a target that keeps moving."},
    {"id":"d-0147","situation":"winning-streak","lead":"Consistency is the least glamorous thing in football and the most valuable.","co":"{winnerClub} know it better than anyone. Glamour is the trailer, consistency is the film."},
    {"id":"d-0148","situation":"winning-streak","lead":"Everyone else in the table is starting to look like a supporting act.","co":"A supporting act needs a headliner, and this headliner is not budging."},
    {"id":"d-0149","situation":"winning-streak","lead":"The rivalry tilts again, only this time it is a slow and steady lean.","co":"Slow leans are the dangerous ones. They never look dramatic until they are finished."},
    {"id":"d-0150","situation":"winning-streak","lead":"Each time {loser} thinks the spell is over, {winner} adds a fresh chapter.","co":"The author clearly has not put the pen down, and the readers are not complaining."},
    {"id":"d-0151","situation":"winning-streak","lead":"{winner} has won again, and the chain just grew another link.","co":"Chains like that are not built on luck. They come from sound habits, season after season."},
    {"id":"d-0152","situation":"winning-streak","lead":"Win after win for {winnerClub}, and {loser} is searching for an exit.","co":"No gap has opened in ages, so the door stays firmly shut."},
    {"id":"d-0153","situation":"winning-streak","lead":"Nobody holds the summit this long by accident, and {winner} knows it.","co":"Knowing is the easy part. Repeating the right thing without a slip is what counts."},
    {"id":"d-0154","situation":"winning-streak","lead":"The trophy cabinet at {winnerClub} is filling up nicely.","co":"Each season adds a piece, and before long the shelf looks like a fortress."},
    {"id":"d-0155","situation":"winning-streak","lead":"Refusing to let the top spot slip is the whole story for {winner}.","co":"Refusing to let go is how you hold on. Talent alone tends to fade."},
    {"id":"d-0156","situation":"winning-streak","lead":"{winner} makes winning look routine, and {loser} is running out of patience.","co":"Routine is the highest praise in this game. It means nothing is left to chance."},
    {"id":"d-0157","situation":"streak-broken","lead":"{winner} has ended {loser}'s reign, and the room has gone very quiet.","co":"Reigns end the same way every time, with one result the other side cannot answer."},
    {"id":"d-0158","situation":"streak-broken","lead":"Down goes the wall, and {winner} walks through the gap with a grin.","co":"That wall relied on nobody finding the way through. Somebody finally did."},
    {"id":"d-0159","situation":"streak-broken","lead":"The grip has slipped for {loser}, and {winner} is the hand that loosened it.","co":"A grip only works while it stays firm, and this time it simply was not firm enough."},
    {"id":"d-0160","situation":"streak-broken","lead":"The reign ends, and {winner} takes the crown with a shrug.","co":"A shrug can be dangerous. It says {winner} saw this coming and planned for it."},
    {"id":"d-0161","situation":"streak-broken","lead":"There goes the monopoly, and {winner} is the one who flipped the board.","co":"A monopoly needs everyone else to stay quiet, and {winner} made sure they would not."},
    {"id":"d-0162","situation":"streak-broken","lead":"Gone is {loser}'s grip, and {winner} has not even blinked.","co":"Blinking would have been a mistake. Pressure like that was always going to find a crack."},
    {"id":"d-0163","situation":"streak-broken","lead":"There is a new name in charge of this rivalry, and it reads {winner}.","co":"It is not forever, but it is real. Power only shifts when somebody takes it."},
    {"id":"d-0164","situation":"streak-broken","lead":"So that is it. The run is over for {loser}, and {winnerClub} did the ending.","co":"Good endings need a sharper plan, and {winnerClub} brought one right when it counted."},
    {"id":"d-0165","situation":"streak-broken","lead":"The chain snaps, and {winnerClub} are holding the scissors.","co":"Scissors is a fair picture. No drama, just a clean cut when the moment came."},
    {"id":"d-0166","situation":"streak-broken","lead":"{loser} looked untouchable until {winner} walked into the picture.","co":"Nobody stays untouchable forever. This was simply the day the spell broke."},
    {"id":"d-0167","situation":"streak-broken","lead":"{loser} has finally lost the lead, and the whole rivalry feels different now.","co":"Every long reign leaves the old certainty behind, and the contest opens up again."},
    {"id":"d-0168","situation":"streak-broken","lead":"The sequence is over, and {winner} has the honour of ending it.","co":"Honour is the right word. Stopping a run like that takes a plan as well as nerve."},
    {"id":"d-0169","situation":"opening-season","lead":"The curtain rises, and {winner} takes the first bow.","co":"Bows are earned on the night, not promised in the programme. This one was earned."},
    {"id":"d-0170","situation":"opening-season","lead":"{winnerClub} have fired the opening salvo and hit the target.","co":"A salvo only counts if it lands, and landing it first is a fine way to be taken seriously."},
    {"id":"d-0171","situation":"opening-season","lead":"That prologue belongs to {winner}, and it reads beautifully.","co":"Prologues set expectations. Whether the chapters match them is the real question."},
    {"id":"d-0172","situation":"opening-season","lead":"{loser} stumbles out of the blocks and {winnerClub} pounce.","co":"Stumbles are normal at the start. What matters is how fast the other side finds its feet."},
    {"id":"d-0173","situation":"opening-season","lead":"Season {seasonNo} is in the books, and {winner} holds the early advantage.","co":"Early advantages are real, but they guarantee nothing at all."},
    {"id":"d-0174","situation":"opening-season","lead":"The maiden result is in, and it is {winner} by {margin}.","co":"A margin of {margin} is a sound introduction. It settles nothing but sets the mood nicely."},
    {"id":"d-0175","situation":"opening-season","lead":"Nobody knew what to expect, and now we know {winner} got the better footing.","co":"Better beginnings are welcome, but plenty of fast starters fade long before the finish."},
    {"id":"d-0176","situation":"opening-season","lead":"Swinging from the very first bell, {winner} came out ready for a scrap.","co":"Swinging is fun, but it has to be backed up with steady results afterwards."},
    {"id":"d-0177","situation":"opening-season","lead":"The overture belongs to {winnerClub} while {loserClub} reread the sheet music.","co":"Rereading is sensible. Sheet music can be rewritten, and the next movement counts for more."},
    {"id":"d-0178","situation":"opening-season","lead":"A maiden win for {winner}, and the rivalry has its opening line.","co":"A strong line matters in a good story. Whether the rest of the book keeps pace is another matter."},
    {"id":"d-0179","situation":"opening-season","lead":"{loser} will want that result back, and {winner} will want it framed.","co":"Framing is lovely. A strong beginning is worth looking back on when the going gets tough."},
    {"id":"d-0180","situation":"opening-season","lead":"A launch win for {winnerClub}, and the standings have a new leader.","co":"Leaders change fast in these early days, so nobody should get comfortable yet."},
    {"id":"d-0181","situation":"halfway","lead":"Halfway through, and {leader} is the one everybody else is trying to catch.","co":"Tough job, because every rival now studies the man ahead and hunts for cracks."},
    {"id":"d-0182","situation":"halfway","lead":"The interval arrives, and {trailer} is breathing down the front man's neck.","co":"Close enough to pounce if {leader} drops off, and that is the whole plan from here."},
    {"id":"d-0183","situation":"halfway","lead":"We reach the turn of the campaign, and the summit is up for grabs.","co":"Nobody has nailed it down, so every patch of good form from now on will decide the owner."},
    {"id":"d-0184","situation":"halfway","lead":"At the centre of the run the standings look tight, and the neutrals are loving it.","co":"Tight is the best news for anyone watching, since the big moves are still to come."},
    {"id":"d-0185","situation":"halfway","lead":"The finish line is already in sight, and the pacesetter can almost taste it.","co":"Tasting it is the easy bit. The trick is keeping the legs fresh for the final stretch."},
    {"id":"d-0186","situation":"halfway","lead":"At the midway mark the gap is only {margin}, which is next to nothing.","co":"A gap that small can vanish in a single purple patch, so nobody should relax."},
    {"id":"d-0187","situation":"halfway","lead":"The halfway mark has arrived, and {trailer} has the look of a hungry hunter.","co":"Hungry is right. The hunter has studied the favourite and is waiting for the first wobble."},
    {"id":"d-0188","situation":"halfway","lead":"Half of the Showdown is gone, and it is still anybody's game.","co":"The heart of the run is where early advantages get eaten away, so nobody can switch off."},
    {"id":"d-0189","situation":"halfway","lead":"The mood has swung all campaign, and everyone is afraid to call it.","co":"Swings are what a campaign does to people. The table only settles once results stop surprising us."},
    {"id":"d-0190","situation":"halfway","lead":"At the midpoint {leader} has built a little breathing room at the summit.","co":"Breathing room is handy now, but a bad spell can take it away fast."},
    {"id":"d-0191","situation":"halfway","lead":"Past the interval, and {trailer} is making all the right noises in the background.","co":"Noises in the background are what hunters do, and the man in front would be foolish to ignore them."},
    {"id":"d-0192","situation":"halfway","lead":"The midway point gives us our sharpest picture yet of who is genuinely serious.","co":"A picture this sharp is still a snapshot and not a verdict, so do not frame it yet."},
    {"id":"d-0193","situation":"final-season-decider","lead":"Crunch time has arrived, and {leader} still holds the edge at the top.","co":"An edge is useful, but the run-in is all about who keeps a cool head when nerves kick in."},
    {"id":"d-0194","situation":"final-season-decider","lead":"A final lap to run, and {trailer} is close enough to smell the prize.","co":"Close is never enough on its own. The chaser needs the leader to slip."},
    {"id":"d-0195","situation":"final-season-decider","lead":"The curtain is about to rise on the closing act, and it is wide open.","co":"Wide open means one wrong decision could settle everything, so nobody can relax."},
    {"id":"d-0196","situation":"final-season-decider","lead":"Every manager is staring at the home straight, and no one is looking away.","co":"That is where character shows, and where the rest of us find out who they really are."},
    {"id":"d-0197","situation":"final-season-decider","lead":"Last lap of the Showdown, and {leader} has to hold the line.","co":"Holding the line sounds simple, but it is the hardest job in football once pressure lands."},
    {"id":"d-0198","situation":"final-season-decider","lead":"The decider is here, with {margin} between the pair and everything still to play for.","co":"A gap of {margin} is nothing when the finale is this close, since one bad spell can flip it."},
    {"id":"d-0199","situation":"final-season-decider","lead":"This is the endgame, and every corner of the table is still alive.","co":"Every corner counts now, since the run-in leaves no room for second thoughts."},
    {"id":"d-0200","situation":"final-season-decider","lead":"The finale of these {seasonsTotal} seasons is about to begin, and nothing is settled.","co":"Nothing settled at this stage is what makes the wait worth it, because every point counts."},
    {"id":"d-0201","situation":"final-season-decider","lead":"A decider with the table so tight you could slide paper between them.","co":"Tight tables are a nightmare for the managers and a treat for everyone else."},
    {"id":"d-0202","situation":"final-season-decider","lead":"Season {seasonNo} is the big one, and {trailer} needs a spark to catch up.","co":"A challenger needs a big surge and a steady head, and a spark is only the start."},
    {"id":"d-0203","situation":"final-season-decider","lead":"The clock is ticking down, and the deciding moment of this Showdown is in sight.","co":"Countdowns make everyone check their notes and their nerves, and this one is no different."},
    {"id":"d-0204","situation":"final-season-decider","lead":"We are looking at the last lap, and {leader} has a little cushion.","co":"A cushion is comforting now, but one ropey spell of form can deflate it in a flash."},
    {"id":"d-0205","situation":"showdown-won","lead":"It is over, and {winner} has taken the whole contest.","co":"The side that stayed sharpest across {seasonsTotal} seasons takes the prize, and rightly so."},
    {"id":"d-0206","situation":"showdown-won","lead":"The final whistle has gone, and the manager in front has the prize.","co":"Champions are built over the long haul, and this one kept its shape from start to finish."},
    {"id":"d-0207","situation":"showdown-won","lead":"{loser} can only tip a cap as {winner} walks away with the lot.","co":"A tip of the cap is the fitting response. The consistency on display was simply too much."},
    {"id":"d-0208","situation":"showdown-won","lead":"The last word is in, and it belongs to {winnerClub}.","co":"Quite fitting. The form was there from the first campaign to the last and never faded."},
    {"id":"d-0209","situation":"showdown-won","lead":"This feud is over, and the trophy has a new owner.","co":"A journey like that is never about one big moment. It is about turning up strong every time."},
    {"id":"d-0210","situation":"showdown-won","lead":"The overall table closes {winnerPoints} to {loserPoints}, and {winner} is king of the hill.","co":"Totals never lie, and a finish like that comes from a steady road to the top."},
    {"id":"d-0211","situation":"showdown-won","lead":"{winner} beats {loser} to the crown by {margin} points overall.","co":"A margin of {margin} might look small, but a deserved win is still a deserved win."},
    {"id":"d-0212","situation":"showdown-won","lead":"The Showdown belongs to {winnerClub}, and the gap closed out at {margin}.","co":"Closing out at {margin} means the lead was never really in doubt once the middle was done."},
    {"id":"d-0213","situation":"showdown-won","lead":"It is all settled at the top, and {winner} is lifting the silverware.","co":"Lifting it means keeping cool in the closing moments, and that is exactly what {winner} did."},
    {"id":"d-0214","situation":"showdown-won","lead":"And that is the battle, with {winner} taking it and {loser} offering a generous nod.","co":"A nod is the fitting gesture. Rivalry is only fun when the loser can still laugh afterwards."},
    {"id":"d-0215","situation":"showdown-won","lead":"It is finished, and the one holding the trophy aloft is {winner}.","co":"Holding it aloft is the reward for every sensible decision across the entire run."},
    {"id":"d-0216","situation":"showdown-won","lead":"Lights down on this race, and {winnerClub} are the last club standing.","co":"Standing at the end is the whole point. The campaign rewards whoever keeps going longest."},
    {"id":"d-0217","situation":"showdown-drawn","lead":"Full stop on {seasonsTotal} seasons, and the pair sit on exactly {points} apiece.","co":"Two careers in perfect step for that long means no lucky spell, only consistency."},
    {"id":"d-0218","situation":"showdown-drawn","lead":"Nobody takes the trophy home, because {managerA} and {managerB} end level.","co":"Neither lost and neither won, so the bragging rights stay split down the middle."},
    {"id":"d-0219","situation":"showdown-drawn","lead":"{clubA} and {clubB} have swapped the top spot all the way through the campaign.","co":"Changing places that often and still ending even says neither side ever gave an inch."},
    {"id":"d-0220","situation":"showdown-drawn","lead":"No winner, no loser, just {managerA} and {managerB} standing even at the death.","co":"Level at the very end is the hardest thing to earn, because every season was fought for."},
    {"id":"d-0221","situation":"showdown-drawn","lead":"Bragging rights go to no one, so {clubA} and {clubB} can sit back and smirk.","co":"Smirking is allowed. Neither side collapsed and neither got lucky along the way."},
    {"id":"d-0222","situation":"showdown-drawn","lead":"Two clubs, {seasonsTotal} seasons, and the ledger refuses to pick a champion.","co":"The ledger is honest about it, because both sides earned exactly the same haul."},
    {"id":"d-0223","situation":"showdown-drawn","lead":"A neck and neck run, and {managerA} is already demanding a rematch.","co":"Fair enough, since {managerB} is already asking for the very same thing."},
    {"id":"d-0224","situation":"showdown-drawn","lead":"The next round is being drawn up, and {managerA} wants first pick.","co":"Good luck with that, because {managerB} has been plotting the same opening for ages."},
    {"id":"d-0225","situation":"showdown-drawn","lead":"Not a wobble, not a collapse, not a single lucky break across the whole run.","co":"That is why it satisfies. Two steady operators and not a flicker of panic."},
    {"id":"d-0226","situation":"showdown-drawn","lead":"The pair finish level on {points}, which is either beautiful or infuriating.","co":"Beautiful for everyone watching, and faintly infuriating for the two people who lived it."},
    {"id":"d-0227","situation":"showdown-drawn","lead":"A quiet draw between {clubA} and {clubB}, and nobody gets to lift anything.","co":"Quiet is not dull, though. Every one of those seasons was a proper scrap."},
    {"id":"d-0228","situation":"showdown-drawn","lead":"Neither side gets a lap of honour, just a handshake at the centre circle.","co":"A handshake fits. Nobody can claim the stage and nobody has to slink off alone."},
    {"id":"d-0229","situation":"golden-showdown","lead":"{leader} is closing in on the threshold, and {trailer} has to chase every point.","co":"Chasing is the right word, because only one manager's own total counts here."},
    {"id":"d-0230","situation":"golden-showdown","lead":"The finishing tape is in sight, and only {leader} is close enough to grab it.","co":"Only a single manager's total counts, so {trailer} cannot sneak in on a shared score."},
    {"id":"d-0231","situation":"golden-showdown","lead":"{trailer} is hunting the summit now, and every season from here is a must-win.","co":"Harsh but accurate. The crown goes to whoever reaches the top first, with no consolation."},
    {"id":"d-0232","situation":"golden-showdown","lead":"The top step is just ahead, and {leader} has a clear run at it in season {seasonNo}.","co":"A clear run is all a closer needs, because the crown goes to whoever gets there first."},
    {"id":"d-0233","situation":"golden-showdown","lead":"Out in front by {margin}, {leader} sees the finish closer than ever.","co":"Closer than ever is not the same as there, and {trailer} still has a push left."},
    {"id":"d-0234","situation":"golden-showdown","lead":"A bold step toward the peak from {trailer}, and the room gasps.","co":"Gasps are fair, because one bold season can change the whole picture in a hurry."},
    {"id":"d-0235","situation":"golden-showdown","lead":"It is a solo race and not a relay, and {leader} is carrying every single step.","co":"A relay would share the weight. Here each manager carries only their own load to the top."},
    {"id":"d-0236","situation":"golden-showdown","lead":"The threshold is glowing, and {leader} can almost reach out and touch it.","co":"Almost touching is dangerous, because the first manager over the mark takes the whole crown."},
    {"id":"d-0237","situation":"golden-showdown","lead":"{winner} has crossed the golden line first, and the Golden Showdown is decided.","co":"First over the line takes it outright, and nobody gets a half share of the glory."},
    {"id":"d-0238","situation":"golden-showdown","lead":"The summit is reached by {winner}, and the Showdown has its champion, just like that.","co":"Just like that is how these races end. One total got there while the other was still climbing."},
    {"id":"d-0239","situation":"golden-showdown","lead":"{winnerClub} are first to the peak, and {loserClub} can only tip their caps.","co":"Tipping caps is right, because the crown goes to whichever single manager arrives first."},
    {"id":"d-0240","situation":"golden-showdown","lead":"The golden prize goes to {winner} in season {seasonNo}, and with a flourish.","co":"A flourish suits it, because the first manager over the mark walks away with the lot."},
    {"id":"d-0241","situation":"one-season-sprint","lead":"No second act is coming, and {winner} has the entire contest in hand.","co":"That is the cruel beauty of a quickfire format. There is no time to recover from a bad start."},
    {"id":"d-0242","situation":"one-season-sprint","lead":"All done this season, and {winnerClub} walk away with the lot.","co":"Fast and final. A campaign like this leaves no room for a comeback, and that is the point."},
    {"id":"d-0243","situation":"one-season-sprint","lead":"{winnerPoints} to {loserPoints}, and that is the entire Showdown settled.","co":"The full story sits in this one season, so every point had to be fought for right then."},
    {"id":"d-0244","situation":"one-season-sprint","lead":"A quickfire Showdown, and {winnerClub} cross the line {margin} clear.","co":"A margin like that, in a single season, reflects a dominant display across the board."},
    {"id":"d-0245","situation":"one-season-sprint","lead":"Second chances do not exist here, and {loser} knew it before the final whistle.","co":"Knowing early is the hardest part, because the season had already decided the outcome."},
    {"id":"d-0246","situation":"one-season-sprint","lead":"{winnerClub} took it, {loserClub} did not, and it was over before anyone blinked.","co":"Blinking is for longer contests. The sprint ends the moment the last point lands."},
    {"id":"d-0247","situation":"one-season-sprint","lead":"{winnerPoints} points to {loserPoints}, a result nobody saw coming in the warm-up.","co":"Warm-ups never tell you much. The season always has the final word."},
    {"id":"d-0248","situation":"one-season-sprint","lead":"Settled at once, and {winner} steps forward with the Showdown in both hands.","co":"Both hands is a fair image, because there was no time for anyone else to grab a piece."},
    {"id":"d-0249","situation":"one-season-sprint","lead":"{loserClub} had a lone shot, and it went wide.","co":"A lone shot is all a dash gives you, and it is harsh on anyone who misses."},
    {"id":"d-0250","situation":"one-season-sprint","lead":"The race is over, and {winner} crosses the line with {margin} to spare.","co":"Room to spare means the season never threatened to slip away."},
    {"id":"d-0251","situation":"one-season-sprint","lead":"No comeback was needed for {winner}, because there was never time for one.","co":"A brief campaign rewards the side that starts sharp and stays sharp all the way."},
    {"id":"d-0252","situation":"one-season-sprint","lead":"A quick settle for {winnerClub}, and {loserClub} can only admire the speed.","co":"Speed is the nature of this format. Nobody gets a long build-up to change their mind."},
    {"id":"d-0253","situation":"dominant-run","lead":"Every season so far has gone {leader}'s way, and {trailer} is still knocking on the door.","co":"Knocking is polite, but a run like this needs a crowbar, and {trailer} has not brought one."},
    {"id":"d-0254","situation":"dominant-run","lead":"No slips, no sulks and no excuses, as {leader} runs this Showdown like a well-oiled machine.","co":"Machines do not get tired, which is terrible news for anyone trying to catch one."},
    {"id":"d-0255","situation":"dominant-run","lead":"With every campaign taken, {leader} makes the rest feel like a formality.","co":"A contest becomes a formality when the result stays put, and {trailer} has stopped pretending otherwise."},
    {"id":"d-0256","situation":"dominant-run","lead":"Every time {trailer} edges closer, {leader} simply pulls further clear.","co":"Pulling clear is {leader}'s favourite trick, and it has never needed a rehearsal."},
    {"id":"d-0257","situation":"dominant-run","lead":"Not once has {leader} dropped a round, and {trailer} is running short of new ideas.","co":"New ideas are cheap to dream up and expensive to test, and {trailer} has tested the lot."},
    {"id":"d-0258","situation":"dominant-run","lead":"{leader} is the standard now, and every other manager gets measured against it.","co":"A standard only stays one while nobody can reach it, and {trailer} is still reaching."},
    {"id":"d-0259","situation":"dominant-run","lead":"Here is the cruel thing about a dominant run. It makes everyone else doubt themselves.","co":"Doubt is an unwelcome passenger, and {trailer} has shared the back seat with it for ages."},
    {"id":"d-0260","situation":"dominant-run","lead":"Each rival counterattack gets treated by {leader} as a minor inconvenience.","co":"Inconveniences are irritating until you run out of patience, and {trailer} is close to empty."},
    {"id":"d-0261","situation":"dominant-run","lead":"{trailer} has tried every trick in the book, and {leader} has answered each one.","co":"Answering every trick is what a prepared manager does, not a lucky one."},
    {"id":"d-0262","situation":"dominant-run","lead":"Planning the next campaign already, {leader} leaves the chaser still nursing the last one.","co":"Nursing wounds takes time, and a dominant run leaves plenty of them open."},
    {"id":"d-0263","situation":"dominant-run","lead":"Ask {trailer} what they want from this race and the answer is a single crack.","co":"Cracks are hard to find in form like this, and {leader} has polished the surface all year."},
    {"id":"d-0264","situation":"dominant-run","lead":"The benchmark is {leader}, and {trailer} is still searching for the route to it.","co":"A benchmark only helps if somebody can reach it, and nobody has managed it yet."},
    {"id":"d-0265","situation":"rivalry-history","lead":"{managerA} and {managerB} have been circling each other for {seasonsTotal} seasons now.","co":"Circling is the polite term, because neither has ever stopped looking over the fence."},
    {"id":"d-0266","situation":"rivalry-history","lead":"{clubA} against {clubB} has never been a simple affair, and it never will be.","co":"Simple affairs are forgettable, and this one has been unforgettable from the very start."},
    {"id":"d-0267","situation":"rivalry-history","lead":"Some rivalries fade with time, but {managerA} and {managerB} only get louder.","co":"Louder is right, because each season hands the pair fresh reasons to argue."},
    {"id":"d-0268","situation":"rivalry-history","lead":"{managerB} still brings up that old business with {clubA}, and {managerA} refuses to let it go.","co":"Old business keeps the pot simmering, and nobody involved is ready to file it away."},
    {"id":"d-0269","situation":"rivalry-history","lead":"What keeps {managerA} and {managerB} going is simple, and it is pride, plenty of it.","co":"Pride is the glue here, and both sides have enough of it to fill a trophy room."},
    {"id":"d-0270","situation":"rivalry-history","lead":"Collisions have followed {clubA} and {clubB} for as long as this Showdown has existed.","co":"Collisions leave bruises, and these two keep collecting them season after season."},
    {"id":"d-0271","situation":"rivalry-history","lead":"The trouble with this feud is that nobody on either side knows when to quit.","co":"Quitting was never on the menu. The pair would rather keep swinging than admit it."},
    {"id":"d-0272","situation":"rivalry-history","lead":"Ask {managerA} about {managerB} and you will get a sigh, a grin and a full history lesson.","co":"The sigh is for the hard years, the grin for the good ones, and the lesson for anyone listening."},
    {"id":"d-0273","situation":"rivalry-history","lead":"Two managers trade sharp words all the time, yet share a friendship worth keeping.","co":"Sharp words are part of the deal, and the friendship has survived every single one."},
    {"id":"d-0274","situation":"rivalry-history","lead":"Never once has {managerA} let {managerB} forget a moment from the early campaigns.","co":"Memory is a weapon in this rivalry, and each keeps sharpening theirs."},
    {"id":"d-0275","situation":"rivalry-history","lead":"The grudges are hardly grudges now, as they have become rituals both look forward to.","co":"A ritual is sweeter than a grudge, and each would miss the other if it stopped."},
    {"id":"d-0276","situation":"rivalry-history","lead":"{managerA} would never say it aloud, but {managerB} has become a favourite opponent.","co":"Favourite opponent is high praise from a rival, even when it arrives with a sneer."},
    {"id":"d-0277","situation":"season-preview","lead":"Season {seasonNo} is about to begin, and {managerA} and {managerB} stare at the same blank page.","co":"A blank page is the most dangerous thing in a rivalry, because anything can be written on it."},
    {"id":"d-0278","situation":"season-preview","lead":"Into the campaign goes {leader} holding the lead, and {trailer} has a point to prove.","co":"Points to prove make the best motivation, but a lead is only as safe as the next campaign."},
    {"id":"d-0279","situation":"season-preview","lead":"Nothing is decided yet, and the next phase of this Showdown sits face down on the table.","co":"Face-down cards are the most exciting thing in any game, right up until somebody turns one over."},
    {"id":"d-0280","situation":"season-preview","lead":"{clubA} and {clubB} are raring to go, and both look like they planned all night.","co":"Planning all night is the easy part. The true test is first contact with reality."},
    {"id":"d-0281","situation":"season-preview","lead":"After {seasonsTotal} seasons the rivalry is as hot as ever heading into season {seasonNo}.","co":"Heat like that does not cool with time. It simply moves on to the next challenge."},
    {"id":"d-0282","situation":"season-preview","lead":"Bold promises are flying before the campaign begins, and {managerA} has made a few big ones.","co":"Promises are cheap until the table starts telling the truth."},
    {"id":"d-0283","situation":"season-preview","lead":"Champions League talk is loud, and {managerA} says the cabinet has room for more.","co":"Cabinets only fill when trophies are actually won, and nobody can promise that bit."},
    {"id":"d-0284","situation":"season-preview","lead":"A strong opening to season {seasonNo} is what {trailer} needs, and the old hands can see it.","co":"A strong opening will not be enough alone, but a weak one would be a real problem."},
    {"id":"d-0285","situation":"season-preview","lead":"Up at the top sits {leader}, and the term ahead will test that seat.","co":"The top is comfortable until the new campaign reminds everyone how quickly that changes."},
    {"id":"d-0286","situation":"season-preview","lead":"What will {clubA} do in season {seasonNo}? Nobody knows yet, and that is the fun part.","co":"Not knowing is half the fun, and {clubB} is probably wondering the very same thing."},
    {"id":"d-0287","situation":"season-preview","lead":"Each manager spent the break on their plans, and now the moment of truth is close.","co":"Plans look wonderful on paper. The moment of truth is when they meet the Showdown."},
    {"id":"d-0288","situation":"season-preview","lead":"Sleeves are already rolled for {managerA} and {managerB} before the opener.","co":"Ready sleeves are a good sign, but the trick is keeping them ready when it starts to hurt."}
  ]);
  const SMALL=Object.freeze({briefs:freeze([
    {"situation":"champions-league","head":"THE CONTINENT'S CROWN","text":"The continent's top prize now lives under glass, and the club has promised that the polishing cloth comes out every single morning."},
    {"situation":"champions-league","head":"TOP SHELF TENANT","text":"The biggest trophy in the building has finally found a home, and the manager placed it on the top shelf as though it might bruise."},
    {"situation":"champions-league","head":"A BIGGER KEY","text":"The club needed a larger key for this prize, since the continental crown would not fit through any ordinary cupboard door."},
    {"situation":"champions-league","head":"LATE-NIGHT LETTERING","text":"The engraver worked into the small hours on the continental plate, and the manager checked every letter with a magnifying glass."},
    {"situation":"champions-league","head":"RIBBON PRESSED FLAT","text":"The medal that matters most across the continent has a new owner, and its ribbon has been ironed with great ceremony."},
    {"situation":"champions-league","head":"ABOVE ALL SILVER","text":"No display on the continent sits higher than this one, where the crown now rests above every other piece of silver."},
    {"situation":"champions-league","head":"SPOTLIGHT, PLEASE","text":"Hand over the key, because the continental prize is ready for its spotlight and the glass has never looked brighter."},
    {"situation":"champions-league","head":"HOMEWARD BOUND SILVER","text":"Carried home in careful hands, the continent's top silver has arrived and the case already looks a little small for the occasion."},
    {"situation":"champions-league","head":"POLISH BEFORE PHOTOS","text":"The photographers are coming, so the manager has gathered every cloth in the house and started work on the big gold piece."},
    {"situation":"champions-league","head":"A FRESH PAGE","text":"Lifting the continent's most famous prize leaves the record books needing a clean page, and they have quietly reserved one."},
    {"situation":"champions-league","head":"FACING THE DOOR","text":"The continental crown is back home, placed facing the door so that no visitor can possibly miss it."},
    {"situation":"champions-league","head":"THE LOCK CLICKS","text":"The top case has been locked, and its only key hangs on a ribbon around the manager's neck, which is quite the fashion statement."},
    {"situation":"champions-league","head":"NAME ON THE PLATE","text":"A plate bearing the continent's name is being engraved this very hour, with fresh letters soon to sit beside the glass."},
    {"situation":"champions-league","head":"UP THE STAIRS","text":"The grandest trophy in club football was carried up the stairs and set down in the best case in the house."},
    {"situation":"champions-league","head":"FINEST POLISH IN TOWN","text":"Few silver pieces on the continent shine like this one, and the club has bought the best polish in town to keep it that way."},
    {"situation":"europa-league","head":"A SHELF OF ITS OWN","text":"The Europa silver has been given a shelf of its own, polished to a shine, and the manager insists it will never sit in the dark."},
    {"situation":"europa-league","head":"VELVET AND GLASS","text":"It may not be the continent's top prize, but it has a glass case, a velvet cloth and a spot near the door."},
    {"situation":"europa-league","head":"THE OTHER CROWN","text":"The continent's other prize was lifted with the same care given to any silver in the room, and the ribbon looks finer for it."},
    {"situation":"europa-league","head":"CRISP ENOUGH TO CUT","text":"The engraver is cutting the club's name onto a modest plate, and the letters are so crisp they could slice the glass."},
    {"situation":"europa-league","head":"WORTH THE RUBBING","text":"Every cloth in the house has been spent on this prize, and a fresh smudge still turns up to be wiped away each evening."},
    {"situation":"europa-league","head":"DUST NO MORE","text":"The shelf once held nothing but dust, and now a European prize stands proudly in front of the older silver."},
    {"situation":"europa-league","head":"A KEY TURNS","text":"The key turned on the European case with a flourish, and the spare vanished into a waistcoat pocket for safekeeping."},
    {"situation":"europa-league","head":"A NEW LODGER","text":"A new lodger has moved into the glass case, and the manager has promised it a clean window, good light and steady polishing."},
    {"situation":"europa-league","head":"THE LONG ROAD","text":"Some prizes take a long road to the shelf, and this continental piece was earned the hard way, through every round."},
    {"situation":"europa-league","head":"RUBBED TO A GLEAM","text":"The polish is out again, and the continental prize is being rubbed until its engraving catches the lamplight across the room."},
    {"situation":"europa-league","head":"LAST TOUCH OF SILVER","text":"Before the case closes for the evening, a last small piece of silver goes onto the shelf where it has long been missed."},
    {"situation":"europa-league","head":"SIDE SHELF GLOWS","text":"On the side shelf a European prize glows under the lamp, and visitors are asked to admire it without fingerprints."},
    {"situation":"league-title","head":"TISSUE AND TITLE","text":"The league title has been wrapped in tissue and placed in the cabinet, where its tarnish-free shine is admired each morning."},
    {"situation":"league-title","head":"SHARP LETTERING","text":"The league shield now carries fresh engraving, and the lettering is sharp enough to read from the far end of the shelf."},
    {"situation":"league-title","head":"DEAD CENTRE","text":"The league crown sits in the exact centre of the cabinet now, rubbed until the reflection is just right."}
  ]),captions:freeze([
    {"photo":"lead-season","text":"{winner} stands alone under the results stage lights, beside a board that has plainly made up its mind."},
    {"photo":"lead-season","text":"{loser} studies the season sheet with the calm of someone already drafting the reply."},
    {"photo":"lead-season","text":"Shelves dusted and glass gleaming, everything is exactly as promised when {winner} arrives."},
    {"photo":"lead-season","text":"Rows of engraved plates line the wall as {loserClub} waits for the final name to be read aloud."},
    {"photo":"lead-season","text":"A long, quiet moment passes between {winner} and the results board before the figures go up."},
    {"photo":"lead-season","text":"Ribbons on the lectern, silver on the sideboard and {winnerClub} ready for its close-up."},
    {"photo":"lead-season","text":"The board glows at the far end of the stage while {loser} checks the cabinet glass one last time."},
    {"photo":"lead-season","text":"An empty velvet case waits by the results desk as {managerA} and {managerB} eye the shelves."},
    {"photo":"lead-season","text":"{winner} steps into the light and the polished floor returns the favour with a very flattering reflection."},
    {"photo":"lead-season","text":"Somewhere behind the curtain {loserClub} is already working on next season's speech."},
    {"photo":"lead-season","text":"The cabinet doors stand open, the cloths are folded and {winnerClub} looks suitably at home."},
    {"photo":"lead-season","text":"A pair of white gloves rests on the lectern, waiting politely for {winner} to pick them up."},
    {"photo":"lead-season","text":"{loser} gives the results board a gracious nod, which is the most generous thing a rival can do."},
    {"photo":"lead-season","text":"Every plate on the wall has been rubbed to a shine, and the newest one is for {winnerClub}."},
    {"photo":"lead-season","text":"The spotlight finds {winner} first, and the rest of the stage settles into respectful shadow."},
    {"photo":"lead-season","text":"On the far shelf {loserClub} keeps a spot warm, just in case the table turns next year."},
    {"photo":"lead-season","text":"{managerA} and {managerB} share the stage but not the view, and the board makes it clear why."},
    {"photo":"lead-draw","text":"Matching cabinets stand side by side while {managerA} and {managerB} regard them with identical expressions."},
    {"photo":"lead-draw","text":"The scales in the trophy room sit perfectly level, loaded with equal silver for {clubA} and {clubB}."},
    {"photo":"lead-draw","text":"Neither name on the wall is polished any brighter, and {managerA} and {managerB} have both checked."},
    {"photo":"lead-draw","text":"A single cloth passes between {managerA} and {managerB}, because fairness demands the glass be shared."},
    {"photo":"lead-draw","text":"Twin shelves, twin spotlights and a results board that politely declines to pick a favourite for {clubA} or {clubB}."},
    {"photo":"lead-draw","text":"{managerA} looks left, {managerB} looks right and the trophy room offers no advantage either way."},
    {"photo":"lead-draw","text":"The ribbon is cut cleanly in half so that {clubA} and {clubB} can each take a piece."},
    {"photo":"lead-draw","text":"Under a perfectly even light, {managerA} and {managerB} read the same line of the same sheet."},
    {"photo":"lead-draw","text":"Both display cases have been wiped down to the same standard, and {clubA} and {clubB} have noticed."},
    {"photo":"lead-draw","text":"A handshake hangs in the air between {managerA} and {managerB}, framed by equal rows of silver."},
    {"photo":"lead-draw","text":"The engraver has been sent home early, since there is no single name to carve for {clubA} or {clubB}."},
    {"photo":"lead-draw","text":"The cabinet keys sit side by side on the lectern, one for {managerA} and one for {managerB}."},
    {"photo":"lead-draw","text":"Level on the board and level in the room, {clubA} and {clubB} share every inch of the spotlight."}
  ]),ears:freeze([
    {"head":"POLISH WATCH","text":"Cloths sharpened, elbows greased, cups visibly nervous"},
    {"head":"KEYS INSIDE","text":"The cabinet key turns, gently, at last"},
    {"head":"SILVER SPECIAL","text":"Buffed so hard it now needs sunglasses"},
    {"head":"ENGRAVED DAILY","text":"Every nameplate read aloud, then read again"},
    {"head":"MEDAL DESK","text":"Ribbons pressed flat, medals hung with pride"},
    {"head":"SHELF SPACE","text":"Measured twice, and the plan is bold"},
    {"head":"ARCHIVE FIND","text":"Old ribbon discovered in a dusty drawer"},
    {"head":"BRASS NOTICE","text":"Plates buffed for the grand reopening"},
    {"head":"KEY HOLDERS","text":"Only the caretaker keeps the spare"},
    {"head":"TROPHY ROOM","text":"Velvet cloth, steady hand, no sneezing"},
    {"head":"PLAQUE PRESS","text":"Every plaque checked for spelling and pride"},
    {"head":"GLASS CASE","text":"Wiped down for guests, and for nerves"},
    {"head":"INSIDE JOB","text":"Someone polished the shelves all night"},
    {"head":"SHINE ALERT","text":"Gold leaf catching the lamps again"},
    {"head":"CABINET CALL","text":"Doors open, silver out, inspection begins"},
    {"head":"RIBBON WATCH","text":"Bows straightened for the cameras, naturally"},
    {"head":"SILVER LINING","text":"Every shelf lined, every label spelled right"},
    {"head":"TOP SHELF","text":"Only the very best gets a step ladder"},
    {"head":"MEDAL RUN","text":"Sorted by weight, then by mood"},
    {"head":"LOCKED AWAY","text":"Some trophies prefer the glass to the crowd"},
    {"head":"ENGRAVING NOW","text":"Names carved into the base tonight"},
    {"head":"DUSTED OFF","text":"Yesterday's dust has been politely escorted out"},
    {"head":"SHELF LIFE","text":"Medals report a very comfortable retirement"},
    {"head":"GLEAM WATCH","text":"Every cup in the room now smirks"},
    {"head":"KEEPER OF KEYS","text":"The keeper keeps a list, and checks it"},
    {"head":"NOTICE BOARD","text":"Pinned to the door: handle with envy"},
    {"head":"CASE CLOSED","text":"Silver lined up, every label facing front"},
    {"head":"SPARKLE INDEX","text":"Brightness rated, sheen index sharply up"},
    {"head":"PALACE GRADE","text":"Polish applied with royal patience"},
    {"head":"HALL OF FAME","text":"Names still climbing the wall of honour"}
  ]),quotes:freeze([
    {"who":"{winner}","situation":"win","text":"Polish that cup until you can see your face in it, then go and find an empty shelf."},
    {"who":"{loser}","situation":"win","text":"I refuse to sulk in the trophy room, {winner}, because the carpet deserves better."},
    {"who":"{managerA}","situation":"draw","text":"Neither of us lifts it today, so the room gets a fresh cloth and a shrug."},
    {"who":"{winner}","situation":"win","text":"Honestly, the trophies do the talking. My job is keeping the ribbons straight."},
    {"who":"{loser}","situation":"win","text":"Mind the silver, {winner}, and please do not use it as a bottle opener."},
    {"who":"{managerB}","situation":"draw","text":"A draw gives nobody the glory, so the least we can do is split the dusting."},
    {"who":"{winner}","situation":"win","text":"Engraving takes ages, so I asked the engraver to leave room for my middle name."},
    {"who":"{loser}","situation":"win","text":"Next season I bring my own cloth, and the silver will know exactly who is coming."},
    {"who":"{managerA}","situation":"draw","text":"A draw keeps the cabinet locked, and I cannot decide whether to thank or blame the key."},
    {"who":"{winner}","situation":"win","text":"Forget the medals. I am in it for the squeak the cabinet door makes."},
    {"who":"{loser}","situation":"win","text":"Your display is gleaming, {winner}, and I am jealous in the most respectful way possible."},
    {"who":"{winner}","situation":"win","text":"The lock sticks, so each time I open the doors I make a proper performance of it."},
    {"who":"{managerB}","situation":"draw","text":"Nobody takes the big gold cup today, which means we get to glare at it together, politely."},
    {"who":"{winner}","situation":"win","text":"Silver is lovely, but the real prize is seeing my name spelled correctly for once."},
    {"who":"{loser}","situation":"win","text":"I have dusted those ribbons again and again, which tells you exactly how I took the news."},
    {"who":"{managerA}","situation":"draw","text":"A draw hands us the same view of the silver, so gloating is off the menu."},
    {"who":"{winner}","situation":"win","text":"Trophies are only metal until somebody polishes them, so I keep a cloth in my pocket."},
    {"who":"{loser}","situation":"win","text":"Well played, {winner}. Please tell the cabinet it can stop looking so smug."},
    {"who":"{managerB}","situation":"draw","text":"With a draw the keys stay in both our pockets, which makes for a very polite standoff."},
    {"who":"{winner}","situation":"win","text":"This room smells of polish and fresh victory, and I am delighted to be its tenant."},
    {"who":"{loser}","situation":"win","text":"Those medals look far too good on someone else, so I shall plan my revenge with a feather duster."},
    {"who":"{winner}","situation":"win","text":"Every proud manager needs a locked door, a warm light and a rival who asks to see inside."},
    {"who":"{managerA}","situation":"draw","text":"We both polish until the silver shows our faces, and nobody can say who looks better."},
    {"who":"{winner}","situation":"win","text":"I keep a shelf for every season, a drawer for the medals and a ribbon for the bad days."},
    {"who":"{loser}","situation":"win","text":"Your name on that plate looks very grand, {winner}, so I will read it while I make tea."},
    {"who":"{managerB}","situation":"draw","text":"A draw will not hand either of us a trophy, but it does hand us a duster and a grin."},
    {"who":"{winner}","situation":"win","text":"Anyone can own a key, {loser}, but only a true champion remembers where the spare is."},
    {"who":"{loser}","situation":"win","text":"My shelf has room for improvement, so I am spending the next few evenings with a saw."},
    {"who":"{managerA}","situation":"draw","text":"No trophy moves tonight, so the room can finally sit down and so can we."},
    {"who":"{winner}","situation":"win","text":"Gold in the case, silver in the drawer and a grin so wide it needs its own shelf."}
  ])});
  return Object.freeze({contentVersion:1,stories:STORIES,duets:DUETS,small:SMALL});
});
